def sentence_spans(text: str) -> list[tuple[int, int]]:
    """Return ``(start, end)`` character spans of the sentences in ``text`` (whitespace-trimmed)."""
    spans: list[tuple[int, int]] = []
    pos = 0
    for m in _BOUNDARY.finditer(text):
        end = m.end(1) if m.group(1) else m.start()
        spans.append((pos, end))
        pos = m.end()
    spans.append((pos, len(text)))
    return [s for s in (_trim(text, a, b) for a, b in spans) if s is not None]

def _trim(text: str, start: int, end: int) -> tuple[int, int] | None:
    while start < end and text[start].isspace():
        start += 1
    while end > start and text[end - 1].isspace():
        end -= 1
    return (start, end) if end > start else None

def __init__(
    self,
    max_tokens: int = 100,
    overlap_tokens: int = 0,
    tokenizer: tiktoken.Encoding | None = None,
) -> None:
    if max_tokens < 1:
        raise ValueError("max_tokens must be >= 1")
    if overlap_tokens < 0 or overlap_tokens >= max_tokens:
        raise ValueError("overlap_tokens must be in [0, max_tokens)")
    self.max_tokens = max_tokens
    self.overlap_tokens = overlap_tokens
    self.tokenizer = tokenizer or default_tokenizer()

def _units(self, text: str) -> list[tuple[int, int, int]]:
    """Sentence (or sub-sentence) spans with token counts, each <= max_tokens."""
    units: list[tuple[int, int, int]] = []
    for start, end in sentence_spans(text):
        n = self._count(text[start:end])
        if n <= self.max_tokens:
            units.append((start, end, n))
            continue
        for cs, ce in self._clause_spans(text, start, end):
            cn = self._count(text[cs:ce])
            if cn <= self.max_tokens:
                units.append((cs, ce, cn))
            else:
                units.extend(self._token_windows(text, cs, ce))
    return units

@staticmethod
def _clause_spans(text: str, start: int, end: int) -> list[tuple[int, int]]:
    spans, pos = [], start
    for m in _CLAUSE.finditer(text, start, end):
        spans.append((pos, m.start()))
        pos = m.end()
    spans.append((pos, end))
    return [s for s in (_trim(text, a, b) for a, b in spans) if s is not None]

def _overlap_tail(self, units: list[tuple[int, int, int]]) -> list[tuple[int, int, int]]:
    if self.overlap_tokens == 0:
        return []
    tail: list[tuple[int, int, int]] = []
    total = 0
    for u in reversed(units):
        if total + u[2] > self.overlap_tokens:
            break
        tail.insert(0, u)
        total += u[2]
    return tail

@staticmethod
def _make(text: str, units: list[tuple[int, int, int]]) -> Chunk:
    start, end = units[0][0], units[-1][1]
    return Chunk(text=text[start:end], start=start, end=end)

@CHUNKERS.register("sentence")
def _make_sentence(max_tokens: int = 100, overlap_tokens: int = 0, **_: object) -> Chunker:
    return SentenceChunker(max_tokens=max_tokens, overlap_tokens=overlap_tokens)

def split_text(
    text: str, tokenizer: tiktoken.Encoding, max_tokens: int, overlap: int = 0
) -> list[str]:
    """Backward-compatible wrapper for the original ``raptor.utils.split_text``."""
    return SentenceChunker(max_tokens, overlap_tokens=overlap, tokenizer=tokenizer).split_texts(
        text
    )

def _spans_between(
    text: str, pattern: re.Pattern[str], start: int, end: int
) -> list[tuple[int, int]]:
    spans, pos = [], start
    for m in pattern.finditer(text, start, end):
        if m.end() == m.start():
            continue
        spans.append((pos, m.start()))
        pos = m.end()
    spans.append((pos, end))
    return [s for s in (_trim(text, a, b) for a, b in spans) if s is not None]

def prose_sentence_spans(text: str, pattern: str = PARAGRAPH_BREAK) -> list[tuple[int, int]]:
    """Sentences that may span wrapped lines; paragraph breaks always end a sentence."""
    out: list[tuple[int, int]] = []
    for ps, pe in paragraph_spans(text, pattern):
        pos = ps
        for m in _SENTENCE_END.finditer(text, ps, pe):
            span = _trim(text, pos, m.end())
            if span:
                out.append(span)
            pos = m.end()
        span = _trim(text, pos, pe)
        if span:
            out.append(span)
    return out

def _fit(self, text: str, start: int, end: int) -> list[Unit]:
    """Split ``text[start:end]`` into units that each fit ``max_tokens``."""
    n = self._count(text[start:end])
    if n <= self.max_tokens:
        return [(start, end, n)]
    units: list[Unit] = []
    for s, e in sentence_spans_in(text, start, end):
        m = self._count(text[s:e])
        if m <= self.max_tokens:
            units.append((s, e, m))
        else:
            units.extend(_shift(SentenceChunker._units(self, text[s:e]), s))
    return units

def __init__(self, *args: object, pattern: str = PARAGRAPH_BREAK, **kwargs: object) -> None:
    super().__init__(*args, **kwargs)  # type: ignore[arg-type]
    self.pattern = pattern

def _units(self, text: str) -> list[Unit]:
    units: list[Unit] = []
    for s, e in paragraph_spans(text, self.pattern):
        units.extend(self._fit(text, s, e))
    return units

def __init__(
    self, *args: object, separators: tuple[str, ...] | list[str] | None = None, **kwargs: object
) -> None:
    super().__init__(*args, **kwargs)  # type: ignore[arg-type]
    self.separators = tuple(separators or self.DEFAULT_SEPARATORS)

def _units(self, text: str) -> list[Unit]:
    span = _trim(text, 0, len(text))
    return self._split(text, span[0], span[1], 0) if span else []

def _split(self, text: str, start: int, end: int, level: int) -> list[Unit]:
    n = self._count(text[start:end])
    if n <= self.max_tokens:
        return [(start, end, n)]
    if level >= len(self.separators):
        return self._token_windows(text, start, end)
    sep = self.separators[level]
    pieces: list[tuple[int, int]] = []
    pos = start
    while True:
        i = text.find(sep, pos, end)
        if i < 0:
            break
        cut = i + len(sep.rstrip()) if sep.strip() else i  # keep the '.' of '. '
        pieces.append((pos, cut))
        pos = i + len(sep)
    pieces.append((pos, end))
    trimmed = [p for p in (_trim(text, a, b) for a, b in pieces) if p is not None]
    if len(trimmed) <= 1:
        return self._split(text, start, end, level + 1)
    out: list[Unit] = []
    for a, b in trimmed:
        out.extend(self._split(text, a, b, level + 1))
    return out

def split(self, text: str) -> list[Chunk]:
    sentences = prose_sentence_spans(text)
    if not sentences:
        return []
    units: list[Unit] = []
    for s, e in sentences:  # sentence-level units, each <= max_tokens
        n = self._count(text[s:e])
        if n <= self.max_tokens:
            units.append((s, e, n))
        else:
            units.extend(_shift(SentenceChunker._units(self, text[s:e]), s))
    if len(units) == 1:
        return [self._make(text, units)]
    emb = np.asarray(
        self.embedding_model.embed_documents([text[s:e] for s, e, _ in units]), dtype=np.float32
    )
    norms = np.linalg.norm(emb, axis=1, keepdims=True)
    norms[norms == 0] = 1.0
    emb = emb / norms
    distance = 1.0 - np.sum(emb[:-1] * emb[1:], axis=1)
    cut_after = set(np.where(distance > np.percentile(distance, self.breakpoint_percentile))[0])

    segments: list[list[Unit]] = [[]]
    for i, u in enumerate(units):
        segments[-1].append(u)
        if i in cut_after:
            segments.append([])
    segments = [s for s in segments if s]
    segments = self._merge_small(segments)

    chunks: list[Chunk] = []
    for seg in segments:
        if sum(u[2] for u in seg) <= self.max_tokens:
            chunks.append(self._make(text, seg))
        else:
            chunks.extend(self._pack(text, seg))
    return chunks

def _merge_small(self, segments: list[list[Unit]]) -> list[list[Unit]]:
    out: list[list[Unit]] = []
    for seg in segments:
        size = sum(u[2] for u in seg)
        if (
            out
            and (size < self.min_tokens or sum(u[2] for u in out[-1]) < self.min_tokens)
            and sum(u[2] for u in out[-1]) + size <= self.max_tokens
        ):
            out[-1] = out[-1] + seg
        else:
            out.append(seg)
    return out

def _pack(self, text: str, units: list[Unit]) -> list[Chunk]:
    chunks: list[Chunk] = []
    current: list[Unit] = []
    length = 0
    for u in units:
        if current and length + u[2] > self.max_tokens:
            chunks.append(self._make(text, current))
            current, length = [], 0
        current.append(u)
        length += u[2]
    if current:
        chunks.append(self._make(text, current))
    return chunks

@CHUNKERS.register("fixed_tokens")
def _make_fixed(max_tokens: int = 100, overlap_tokens: int = 0, **_: object) -> Chunker:
    return FixedTokenChunker(max_tokens=max_tokens, overlap_tokens=overlap_tokens)

@CHUNKERS.register("paragraph")
def _make_paragraph(
    max_tokens: int = 100, overlap_tokens: int = 0, pattern: str = PARAGRAPH_BREAK, **_: object
) -> Chunker:
    return ParagraphChunker(max_tokens=max_tokens, overlap_tokens=overlap_tokens, pattern=pattern)

@CHUNKERS.register("recursive")
def _make_recursive(
    max_tokens: int = 100,
    overlap_tokens: int = 0,
    separators: list[str] | None = None,
    **_: object,
) -> Chunker:
    return RecursiveChunker(
        max_tokens=max_tokens, overlap_tokens=overlap_tokens, separators=separators
    )

@CHUNKERS.register("semantic")
def _make_semantic(
    max_tokens: int = 100,
    overlap_tokens: int = 0,
    embedding_model: BaseEmbeddingModel | None = None,
    breakpoint_percentile: float = 80.0,
    min_tokens: int | None = None,
    **_: object,
) -> Chunker:
    return SemanticChunker(
        max_tokens=max_tokens,
        overlap_tokens=overlap_tokens,
        embedding_model=embedding_model,
        breakpoint_percentile=breakpoint_percentile,
        min_tokens=min_tokens,
    )

def _setup_logging(verbose: bool) -> None:
    from .settings import get_settings

    level = "DEBUG" if verbose else get_settings().log_level
    logging.basicConfig(level=level, format="%(asctime)s %(levelname)s %(name)s: %(message)s")
    for noisy in ("httpx", "httpx2", "google_genai", "numba", "urllib3"):
        logging.getLogger(noisy).setLevel(logging.WARNING)

def _config(path: Path | None):
    from .config import RaptorConfig

    return RaptorConfig.from_yaml(path) if path else RaptorConfig()

@app.command()
def build(
    source: Annotated[
        Path, typer.Argument(help="Text file to index.", exists=True, dir_okay=False)
    ],
    out: Annotated[Path, typer.Option("--out", "-o", help="Directory to write the index to.")],
    config: ConfigOpt = None,
    overwrite: Annotated[bool, typer.Option(help="Replace an existing index at --out.")] = False,
    verbose: VerboseOpt = False,
) -> None:
    """Build an index from a text file."""
    _setup_logging(verbose)
    from .pipeline import RetrievalAugmentation

    if out.exists() and not overwrite:
        raise typer.BadParameter(f"{out} exists; pass --overwrite to replace it")
    ra = RetrievalAugmentation(_config(config))

    def progress(ev: dict) -> None:
        if ev.get("stage") in {"clustering", "done"} or (
            ev.get("stage") == "summarizing" and ev.get("done") == ev.get("total")
        ):
            typer.echo(f"  {ev}")

    tree = ra.add_documents(source.read_text(encoding="utf-8"), progress=progress)
    ra.save(out)
    typer.echo(f"Built {len(tree.all_nodes)} nodes in {tree.num_layers + 1} layers -> {out}")

@app.command()
def ask(
    index: Annotated[Path, typer.Argument(help="Index directory.", exists=True)],
    question: Annotated[str, typer.Argument()],
    config: ConfigOpt = None,
    top_k: Annotated[int | None, typer.Option("--top-k", "-k")] = None,
    show_context: Annotated[bool, typer.Option(help="Print the retrieved nodes.")] = False,
    verbose: VerboseOpt = False,
) -> None:
    """Answer a question from an index."""
    _setup_logging(verbose)
    from .pipeline import RetrievalAugmentation

    ra = RetrievalAugmentation(_config(config), tree=index)
    result = ra.retrieve_nodes(question, top_k=top_k)
    if show_context:
        for r in result.nodes:
            typer.echo(
                f"[layer {r.layer} | node {r.node.index} | sim {r.score:.3f}] {r.node.text[:160]}..."
            )
        typer.echo("")
    for piece in ra.qa_model.stream_answer(result.context, question):
        typer.echo(piece, nl=False)
    typer.echo("")

@app.command()
def info(index: Annotated[Path, typer.Argument(exists=True)]) -> None:
    """Show the structure of an index."""
    from .storage import load_tree

    tree = load_tree(index)
    typer.echo(f"{index}: {len(tree.all_nodes)} nodes, top layer {tree.num_layers}")
    for layer in sorted(tree.layer_to_nodes):
        typer.echo(f"  layer {layer}: {len(tree.layer_to_nodes[layer])} nodes")
    for key in ("embedding_model", "summarization_model", "source"):
        if key in tree.metadata:
            typer.echo(f"  {key}: {tree.metadata[key]}")

@app.command()
def migrate(
    pickle_file: Annotated[
        Path, typer.Argument(exists=True, dir_okay=False, help="Legacy pickled tree.")
    ],
    out: Annotated[Path, typer.Argument(help="Directory for the converted index.")],
) -> None:
    """Convert a tree pickled by the original RAPTOR into the current index format."""
    from .storage import load_legacy_pickle, save_tree

    tree = load_legacy_pickle(pickle_file)
    save_tree(tree, out)
    typer.echo(f"Converted {pickle_file} ({len(tree.all_nodes)} nodes) -> {out}")

def make_clusterer(cfg: ClusteringConfig) -> ClusteringAlgorithm:
    return CLUSTERERS.create(
        cfg.strategy,
        reduction_dimension=cfg.reduction_dimension,
        threshold=cfg.threshold,
        max_cluster_tokens=cfg.max_cluster_tokens,
        random_state=cfg.random_state,
        **cfg.params,
    )

def check_clusters(clusters: list[list[int]], n: int) -> list[list[int]]:
    """Validate and normalise clusters: sorted, de-duplicated, non-empty, full coverage."""
    out = [sorted(set(c)) for c in clusters if c]
    covered = {i for c in out for i in c}
    if covered != set(range(n)):
        missing = sorted(set(range(n)) - covered)
        raise ValueError(f"clustering left indices unassigned: {missing[:10]}")
    return out

def _fit_gmm(x: np.ndarray, n: int, random_state: int) -> GaussianMixture | None:
    """Fit a GMM, returning ``None`` if it is degenerate (e.g. collapsed points)."""
    try:
        return GaussianMixture(n_components=n, random_state=random_state).fit(x)
    except ValueError:
        return None

def _optimal_components(x: np.ndarray, max_clusters: int, random_state: int) -> int:
    upper = min(max_clusters, len(x))
    best_n, best_bic = 1, np.inf
    for n in range(1, upper):
        gm = _fit_gmm(x, n, random_state)
        if gm is None:
            continue
        bic = gm.bic(x)
        if bic < best_bic:
            best_n, best_bic = n, bic
    return best_n

def cluster(self, embeddings: np.ndarray, token_counts: Sequence[int]) -> list[list[int]]:
    embeddings = np.asarray(embeddings, dtype=np.float32)
    n = len(embeddings)
    if n != len(token_counts):
        raise ValueError("embeddings and token_counts differ in length")
    if n == 0:
        return []
    clusters = self._cluster_with_limit(np.arange(n), embeddings, np.asarray(token_counts))
    return check_clusters(clusters, n)

def _cluster_with_limit(
    self, idx: np.ndarray, embeddings: np.ndarray, tokens: np.ndarray
) -> list[list[int]]:
    result: list[list[int]] = []
    for members in self._two_level(embeddings[idx]):
        group = idx[members]
        if len(group) == 1 or tokens[group].sum() <= self.max_cluster_tokens:
            result.append(group.tolist())
        elif len(group) == len(idx):
            # Re-clustering made no progress; split in order to guarantee termination.
            half = len(group) // 2
            result.extend(self._cluster_with_limit(group[:half], embeddings, tokens))
            result.extend(self._cluster_with_limit(group[half:], embeddings, tokens))
        else:
            result.extend(self._cluster_with_limit(group, embeddings, tokens))
    return result

@CLUSTERERS.register("raptor_gmm")
def _make_raptor_gmm(
    reduction_dimension: int = 10,
    threshold: float = 0.1,
    max_cluster_tokens: int = 3500,
    random_state: int = 224,
    **params: object,
) -> ClusteringAlgorithm:
    return RaptorGMMClustering(
        reduction_dimension=reduction_dimension,
        threshold=threshold,
        max_cluster_tokens=max_cluster_tokens,
        random_state=random_state,
        **params,  # type: ignore[arg-type]
    )

def __init__(self, max_cluster_tokens: int = 3500, random_state: int = 224) -> None:
    self.max_cluster_tokens = max_cluster_tokens
    self.random_state = random_state

@abstractmethod
def groups(self, emb: np.ndarray, tokens: np.ndarray) -> list[list[int]]:
    """Cluster the rows of ``emb``; return lists of row indices covering every row."""

def cluster(self, embeddings: np.ndarray, token_counts: Sequence[int]) -> list[list[int]]:
    emb = np.asarray(embeddings, dtype=np.float32)
    n = len(emb)
    if n != len(token_counts):
        raise ValueError("embeddings and token_counts differ in length")
    if n == 0:
        return []
    clusters = self._limited(np.arange(n), emb, np.asarray(token_counts))
    clusters = sorted(check_clusters(clusters, n), key=lambda c: (c[0], len(c)))
    return clusters

def _limited(self, idx: np.ndarray, emb: np.ndarray, tokens: np.ndarray) -> list[list[int]]:
    if len(idx) == 1:
        return [idx.tolist()]
    out: list[list[int]] = []
    for members in self.groups(emb[idx], tokens[idx]):
        group = idx[np.asarray(sorted(set(members)), dtype=np.int64)]
        if len(group) == 1 or tokens[group].sum() <= self.max_cluster_tokens:
            out.append(group.tolist())
        elif len(group) == len(idx):  # no progress: split in order
            half = len(group) // 2
            out.extend(self._limited(group[:half], emb, tokens))
            out.extend(self._limited(group[half:], emb, tokens))
        else:
            out.extend(self._limited(group, emb, tokens))
    return out

def _gmm_soft_cov(
    x: np.ndarray, threshold: float, max_clusters: int, random_state: int, covariance_type: str
) -> list[list[int]]:
    from sklearn.mixture import GaussianMixture

    def fit(k: int) -> GaussianMixture | None:
        try:
            return GaussianMixture(
                n_components=k, covariance_type=covariance_type, random_state=random_state
            ).fit(x)
        except ValueError:
            return None

    best, best_bic = None, np.inf
    for k in range(1, max(2, min(max_clusters, len(x)))):
        gm = fit(k)
        if gm is not None and (bic := gm.bic(x)) < best_bic:
            best, best_bic = gm, bic
    if best is None:
        return [list(range(len(x)))]
    probs = best.predict_proba(x)
    clusters: list[list[int]] = [[] for _ in range(best.n_components)]
    for row, p in enumerate(probs):
        labels = np.where(p > threshold)[0]
        if len(labels) == 0:
            labels = np.array([int(np.argmax(p))])
        for lab in labels:
            clusters[int(lab)].append(row)
    return [c for c in clusters if c]

def groups(self, emb: np.ndarray, tokens: np.ndarray) -> list[list[int]]:
    if len(emb) <= 2:
        return [list(range(len(emb)))]
    return _gmm_soft_cov(
        _unit_rows(emb),
        self.threshold,
        self.max_clusters,
        self.random_state,
        self.covariance_type,
    )

def groups(self, emb: np.ndarray, tokens: np.ndarray) -> list[list[int]]:
    from sklearn.decomposition import PCA

    n = len(emb)
    if n <= 3:
        return [list(range(n))]
    dim = max(1, min(self.reduction_dimension, n - 2))
    x = PCA(n_components=dim, random_state=self.random_state).fit_transform(_unit_rows(emb))
    return _gmm_soft(x, self.threshold, self.max_clusters, self.random_state)

def groups(self, emb: np.ndarray, tokens: np.ndarray) -> list[list[int]]:
    from sklearn.cluster import AgglomerativeClustering as Agg

    n = len(emb)
    if n <= 2:
        return [list(range(n))]
    if self.distance_threshold is not None:
        model = Agg(
            n_clusters=None,
            distance_threshold=self.distance_threshold,
            metric="cosine",
            linkage=self.linkage,
        )
    else:
        k = max(1, min(n - 1, round(n / self.target_size)))
        model = Agg(n_clusters=k, metric="cosine", linkage=self.linkage)
    return _labels_to_groups(model.fit_predict(_unit_rows(emb)))

def groups(self, emb: np.ndarray, tokens: np.ndarray) -> list[list[int]]:
    from sklearn.cluster import HDBSCAN

    n = len(emb)
    if n <= max(3, self.min_cluster_size):
        return [list(range(n))]
    if n > self.reduction_dimension + 2:
        neighbors = self.n_neighbors or max(2, int((n - 1) ** 0.5))
        x = _umap(emb, self.reduction_dimension, neighbors, self.random_state)
    else:
        x = _unit_rows(emb)
    labels = HDBSCAN(
        min_cluster_size=self.min_cluster_size, min_samples=self.min_samples, copy=True
    ).fit_predict(x)
    real = sorted(set(labels.tolist()) - {-1})
    if not real:
        return [list(range(n))]
    centroids = np.stack([x[labels == lab].mean(axis=0) for lab in real])
    for i in np.where(labels == -1)[0]:
        labels[i] = real[int(np.argmin(np.linalg.norm(centroids - x[i], axis=1)))]
    return _labels_to_groups(labels)

def __init__(self, max_clusters: int = 50, **kw: Any) -> None:
    super().__init__(**kw)
    self.max_clusters = max_clusters

def groups(self, emb: np.ndarray, tokens: np.ndarray) -> list[list[int]]:
    from sklearn.cluster import KMeans
    from sklearn.metrics import silhouette_score

    n = len(emb)
    if n <= 3:
        return [list(range(n))]
    x = _unit_rows(emb)
    lo = max(2, math.ceil(float(tokens.sum()) / self.max_cluster_tokens))
    hi = min(self.max_clusters, n - 1)
    best_labels, best_score = None, -np.inf
    for k in range(lo, max(lo, hi) + 1):
        if k >= n:
            break
        labels = KMeans(n_clusters=k, n_init=10, random_state=self.random_state).fit_predict(x)
        if len(set(labels.tolist())) < 2:
            continue
        score = silhouette_score(x, labels, metric="cosine")
        if score > best_score:
            best_labels, best_score = labels, score
    if best_labels is None:
        return [list(range(n))]
    return _labels_to_groups(best_labels)

def _best_cuts(
    self, gap_sim: np.ndarray, tokens: np.ndarray, n: int, k: int, lo: int, hi: int
) -> list[int] | None:
    csum = np.concatenate([[0], np.cumsum(tokens)])
    inf = float("inf")
    # best[j][m]: min cost to split rows [0, j) into m segments; back-pointers in prev.
    best = np.full((n + 1, k + 1), inf)
    prev = np.full((n + 1, k + 1), -1, dtype=np.int64)
    best[0][0] = 0.0
    for m in range(1, k + 1):
        for j in range(1, n + 1):
            for size in range(lo, hi + 1):
                i = j - size
                if i < 0:
                    break
                if best[i][m - 1] == inf:
                    continue
                if size > 1 and csum[j] - csum[i] > self.max_cluster_tokens:
                    continue
                cost = best[i][m - 1] + (gap_sim[i - 1] if i > 0 else 0.0)
                if cost < best[j][m]:
                    best[j][m], prev[j][m] = cost, i
    if best[n][k] == inf:
        return None
    cuts, j = [], n
    for m in range(k, 0, -1):
        i = int(prev[j][m])
        if i > 0:
            cuts.append(i)
        j = i
    return sorted(cuts)

def _labels_to_groups(labels: np.ndarray) -> list[list[int]]:
    groups: dict[int, list[int]] = {}
    for i, lab in enumerate(np.asarray(labels).tolist()):
        groups.setdefault(int(lab), []).append(i)
    return sorted(groups.values(), key=lambda g: g[0])

