def patch_old_lines(patch: str) -> dict[str, set[int]]:
    """Lines of each pre-patch file that a unified diff touches.

    Removed lines count; for pure insertions the old line just before the insertion point
    counts, so additions inside a function still point at that function.
    """
    out: dict[str, set[int]] = {}
    path: str | None = None
    old = 0
    for line in patch.splitlines():
        if line.startswith("diff --git "):
            path = None
        elif line.startswith("--- "):
            src = line[4:].strip()
            path = src[2:] if src.startswith("a/") else None
            if path is not None:
                out.setdefault(path, set())
        elif line.startswith("+++ "):
            continue
        elif (m := _HUNK.match(line)) is not None:
            old = int(m.group(1))
        elif path is None:
            continue
        elif line.startswith("-"):
            out[path].add(old)
            old += 1
        elif line.startswith("+"):
            out[path].add(max(1, old - 1))
            out[path].add(old)
        elif line.startswith(" ") or line == "":
            old += 1
    return out

def gold_functions(source: bytes, path: str, lines: Iterable[int]) -> set[str]:
    """Qualified names of the innermost function/method (else class) covering ``lines``."""
    pf = PythonExtractor().parse(source, path)
    found: set[str] = set()
    for ln in lines:
        best = None
        for s in pf.symbols:
            if s.start_line <= ln <= s.end_line and (
                best is None or (s.end_line - s.start_line) < (best.end_line - best.start_line)
            ):
                best = s
        if best is not None:
            found.add(best.qualname)
    return found

def mrr(ranked: Sequence[str], gold: set[str]) -> float:
    for i, item in enumerate(ranked, 1):
        if item in gold:
            return 1.0 / i
    return 0.0

def score_ranking(ranked: Sequence[str], gold: set[str]) -> dict[str, float]:
    out = {f"R@{k}": recall_at(ranked, gold, k) for k in KS}
    out["MRR"] = mrr(ranked, gold)
    return out

def mean_scores(rows: list[dict[str, float]]) -> dict[str, float]:
    if not rows:
        return {}
    return {k: float(np.mean([r[k] for r in rows])) for k in rows[0]}

def rank_from_index(
    index: CodeIndex,
    query: str,
    variant: str,
    *,
    bm25: bool,
    graph: bool,
    k: int = 60,
) -> tuple[list[str], list[str]]:
    """``(files, functions)`` ranked for ``query`` by one tree variant."""
    kinds = VARIANT_KINDS[variant]
    hits = index.search(
        query,
        k,
        kinds=kinds,
        bm25=bm25,
        graph_expansion=graph,
        descend=variant != "symbols",
        routing=variant != "symbols",
    )
    files: list[str] = []
    funcs: list[str] = []
    for h in hits:
        node = index.tree.all_nodes[h.node_index]
        if h.kind in ("symbol", "class", "file"):
            files.append(h.path)
        if h.kind == "symbol":
            for q in node.metadata.get("symbols") or [h.symbol]:
                if q != "<module>":
                    funcs.append(f"{h.path}::{q}")
        elif h.kind == "class":
            funcs.append(f"{h.path}::{h.symbol}")
    return _dedupe(files), _dedupe(funcs)

@classmethod
def build(
    cls,
    index: CodeIndex,
    embedding_model: BaseEmbeddingModel,
    *,
    window: int = 40,
    overlap: int = 10,
) -> LineWindowIndex:
    windows, texts = [], []
    symbols: dict[str, list[tuple[int, int, str]]] = {}
    step = max(1, window - overlap)
    for path in index.files():
        src = (index.repo_path / path).read_text(encoding="utf-8", errors="replace")
        lines = src.splitlines()
        parsed = index._files[path]["parsed"]
        symbols[path] = [
            (s["start_line"], s["end_line"], s["qualname"]) for s in parsed["symbols"]
        ]
        for start in range(0, max(1, len(lines)), step):
            chunk = lines[start : start + window]
            if not any(x.strip() for x in chunk):
                continue
            windows.append((path, start + 1, start + len(chunk)))
            texts.append(f"# {path}:{start + 1}-{start + len(chunk)}\n" + "\n".join(chunk))
            if start + window >= len(lines):
                break
    emb = np.asarray(embedding_model.embed_documents(texts), dtype=np.float32)
    emb /= np.maximum(np.linalg.norm(emb, axis=1, keepdims=True), 1e-9)
    return cls(windows, texts, emb, symbols)

def rank(
    self, query: str, embedding_model: BaseEmbeddingModel, *, bm25: bool, k: int = 60
) -> tuple[list[str], list[str]]:
    q = np.asarray(embedding_model.embed_query(query[:8000]), dtype=np.float32)
    q /= np.linalg.norm(q) or 1.0
    sims = self.embeddings @ q
    dense_rank = [int(i) for i in np.argsort(-sims)[: k * 2]]
    fused: dict[int, float] = {}
    for r, i in enumerate(dense_rank):
        fused[i] = fused.get(i, 0.0) + 1 / (60 + r + 1)
    if bm25:
        if self._bm25 is None:
            self._bm25 = BM25([tokenize(t) for t in self.texts])
        for r, (i, _) in enumerate(self._bm25.top(tokenize(query), k * 2)):
            fused[i] = fused.get(i, 0.0) + 1 / (60 + r + 1)
    order = sorted(fused, key=lambda i: (-fused[i], i))[:k]
    files: list[str] = []
    funcs: list[str] = []
    for i in order:
        path, a, b = self.windows[i]
        files.append(path)
        # Symbols overlapping the window, most specific (shortest span) first.
        spans = sorted(
            (e - s, qn) for s, e, qn in self.symbols.get(path, []) if s <= b and e >= a
        )
        funcs.extend(f"{path}::{qn}" for _, qn in spans)
    return _dedupe(files), _dedupe(funcs)

def judge_answer(
    judge: BaseQAModel, question: str, reference: str, answer: str
) -> dict[str, Any]:
    """Score ``answer`` against ``reference`` with an LLM-judge rubric (1-5 per criterion)."""
    prompt = JUDGE_PROMPT.format(question=question, reference=reference, answer=answer)
    raw = judge.answer_question(prompt, "Return the JSON grade.")
    m = re.search(r"\{.*\}", raw, re.S)
    try:
        data = json.loads(m.group(0)) if m else {}
    except json.JSONDecodeError:
        data = {}
    out: dict[str, Any] = {"raw": raw}
    for key in ("correctness", "completeness", "grounding"):
        try:
            out[key] = float(data.get(key))  # type: ignore[arg-type]
        except (TypeError, ValueError):
            out[key] = float("nan")
    out["comment"] = data.get("comment", "")
    return out

@classmethod
def from_tree(cls, tree: Tree, embedding_model_id: str | None = None) -> Reuse:
    r = cls()
    key = tree.embedding_key
    same_model = embedding_model_id is None or tree.metadata.get("embedding_model") in (
        None,
        embedding_model_id,
    )
    concepts: list[list[str]] = []
    for n in tree.all_nodes.values():
        if same_model and key in n.embeddings:
            r.embeddings[short_hash(n.text)] = np.asarray(n.embeddings[key], np.float32)
        ih = n.metadata.get("input_hash")
        if ih and "summary" in n.metadata:
            r.summaries[ih] = n.metadata["summary"]
        if n.metadata.get("kind") == "concept":
            concepts.append(
                [tree.all_nodes[c].metadata.get("key", "") for c in sorted(n.children)]
            )
    r.concepts = concepts or None
    r.concept_pool = set(tree.metadata.get("concept_pool", []))
    return r

@dataclass
class BuildStats:
    reembedded: int = 0
    resummarized: int = 0
    reused_summaries: int = 0
    reused_embeddings: int = 0

def _first_line(text: str, limit: int = 160) -> str:
    line = text.strip().split("\n", 1)[0] if text.strip() else ""
    return line if len(line) <= limit else line[: limit - 3] + "..."

def _truncate(self, text: str, max_tokens: int) -> str:
    ids = self.tok.encode(text, disallowed_special=())
    if len(ids) <= max_tokens:
        return text
    return self.tok.decode(ids[:max_tokens]) + "\n... (truncated)"

def _embed(self, nodes: Sequence[Node], layer: int) -> None:
    key = self.cfg.embedding_key
    todo: list[Node] = []
    for n in nodes:
        hit = self.reuse.embeddings.get(short_hash(n.text))
        if hit is not None:
            n.embeddings[key] = hit
            self.stats.reused_embeddings += 1
        else:
            todo.append(n)
    self.progress({"stage": "embedding", "layer": layer, "total": len(todo)})
    if todo:
        vectors = self.emb.embed_documents([n.text for n in todo])
        for n, v in zip(todo, vectors, strict=True):
            n.embeddings[key] = np.asarray(v, dtype=np.float32)
        self.stats.reembedded += len(todo)

def _summarize_many(self, prompts_: list[str], layer: int, kind: str) -> list[str]:
    """Summaries for ``prompts_``, reusing previous ones for unchanged prompts."""
    out: list[str | None] = []
    todo: list[int] = []
    for i, p in enumerate(prompts_):
        prev = self.reuse.summaries.get(short_hash(p))
        out.append(prev)
        if prev is None:
            todo.append(i)
        else:
            self.stats.reused_summaries += 1
    total = len(todo)
    self.progress(
        {"stage": "summarizing", "layer": layer, "kind": kind, "done": 0, "total": total}
    )
    if todo:
        length = int(self.cfg.summary.length * 1.6)

        def run(i: int) -> str:
            return self.summ.summarize(prompts_[i], max_tokens=length).strip()

        done = 0
        with ThreadPoolExecutor(max_workers=self.cfg.summary.max_workers) as pool:
            futures = {pool.submit(run, i): i for i in todo}
            for fut, i in futures.items():
                out[i] = fut.result()
                done += 1
                self.progress(
                    {
                        "stage": "summarizing",
                        "layer": layer,
                        "kind": kind,
                        "done": done,
                        "total": total,
                    }
                )
        self.stats.resummarized += len(todo)
    return [o or "" for o in out]

def _fit_children(self, items: list[tuple[str, str]], budget: int) -> str:
    """Format ``(label, summary)`` pairs, trimming each to share ``budget`` tokens."""
    if not items:
        return "(empty)"
    per = max(40, budget // len(items))
    return "\n".join(f"- {label}: {self._truncate(s, per)}" for label, s in items)

def _file_body(self, path: str, pf: ParsedFile, source: str, children: list[Node]) -> str:
    parts = []
    if pf.module_docstring:
        parts.append("Module docstring:\n" + self._truncate(pf.module_docstring, 400))
    if pf.imports:
        imports = list(dict.fromkeys(i.text for i in pf.imports))
        parts.append("Imports:\n" + self._truncate("\n".join(imports), 300))
    if self.cfg.summary.depth == "symbol":
        items = []
        for c in children:
            m = c.metadata
            if m["kind"] == "class":
                items.append((f"class {m['symbol']}", m.get("summary", "")))
            elif m.get("summary"):
                items.append((m.get("signature") or m["symbol"], m["summary"]))
            elif m.get("symbol_kind") == "module":
                items.append(("module-level code", self._truncate(c.text, 150)))
        parts.append(
            "Contents:\n" + self._fit_children(items, self.cfg.summary.file_context_tokens)
        )
    else:
        outline = []
        for s in pf.symbols:
            indent = "  " if s.parent else ""
            doc = _first_line(s.docstring)
            outline.append(f"{indent}{s.signature}" + (f"  # {doc}" if doc else ""))
        if outline:
            parts.append("Outline:\n" + self._truncate("\n".join(outline), 800))
        parts.append(
            "Source:\n```\n"
            + self._truncate(source, self.cfg.summary.file_context_tokens)
            + "\n```"
        )
    return "\n\n".join(parts)

def _build_dirs_and_repo(
    self, repo_name: str, file_nodes: dict[str, Node], readme: str | None
) -> tuple[dict[str, Node], Node]:
    children_of: dict[str, list[tuple[str, str]]] = defaultdict(list)  # dir -> [(kind, name)]
    dirs: set[str] = set()
    for p in file_nodes:
        d = posixpath.dirname(p)
        children_of[d].append(("file", p))
        while d:
            parent = posixpath.dirname(d)
            dirs.add(d)
            if ("dir", d) not in children_of[parent]:
                children_of[parent].append(("dir", d))
            d = parent

    height: dict[str, int] = {}

    def h(d: str) -> int:
        if d not in height:
            subs = [n for k, n in children_of[d] if k == "dir"]
            height[d] = 1 + max((h(s) for s in subs), default=-1)
        return height[d]

    for d in dirs:
        h(d)
    dir_nodes: dict[str, Node] = {}
    max_h = max(height.values(), default=-1)
    for level in range(max_h + 1):
        batch = sorted(d for d in dirs if height[d] == level)
        self._summarize_groups(batch, children_of, file_nodes, dir_nodes, 3 + level, kind="dir")
    repo_layer = 3 + max_h + 1
    readme_txt = (
        f"README excerpt:\n{self._truncate(readme, README_TOKENS)}\n\n" if readme else ""
    )
    self._summarize_groups(
        [""],
        children_of,
        file_nodes,
        dir_nodes,
        repo_layer,
        kind="repo",
        repo_name=repo_name,
        readme=readme_txt,
    )
    repo = dir_nodes.pop("")
    return dir_nodes, repo

def _reuse_concepts(self, by_key: dict[str, int], emb: np.ndarray) -> list[list[int]]:
    """Keep the previous concept memberships; attach new nodes to the nearest concept."""
    assert self.reuse.concepts is not None
    clusters = [[by_key[k] for k in keys if k in by_key] for keys in self.reuse.concepts]
    clusters = [c for c in clusters if c]
    assigned = {i for c in clusters for i in c}
    prev_keys = self.reuse.concept_pool | {k for keys in self.reuse.concepts for k in keys}
    if not clusters:
        return []
    unit = emb / np.maximum(np.linalg.norm(emb, axis=1, keepdims=True), 1e-9)
    centroids = np.stack([unit[c].mean(axis=0) for c in clusters])
    for k, i in by_key.items():
        if i in assigned or k in prev_keys:
            continue
        # Only nodes that are new since the last clustering are attached.
        best = int(np.argmax(centroids @ unit[i]))
        clusters[best].append(i)
    return clusters

def _concept_name(summary: str) -> str | None:
    m = re.search(r"Concept:\s*\**\s*([^\n*]+)", summary)
    return m.group(1).strip().rstrip(".") if m else None

@property
def content_hash(self) -> str:
    return short_hash(self.code)

def top_class(sym: Symbol) -> str | None:
    if sym.kind == "class" or sym.parent:
        return sym.qualname.split(".")[0]
    return None

def relevant_imports(code: str, imports: list[ImportRef]) -> list[str]:
    words = set(re.findall(r"[A-Za-z_]\w*", code))
    picked: list[str] = []
    for imp in imports:
        if imp.bound_name in words and imp.text not in picked:
            picked.append(imp.text)
        if len(picked) >= MAX_HEADER_IMPORTS:
            break
    return picked

def header(leaf: Leaf, imports: list[ImportRef]) -> str:
    crumbs = [leaf.path]
    if leaf.class_name and leaf.symbol_kind != "class":
        crumbs.append(f"class {leaf.class_name}")
    if leaf.symbol_kind in ("function", "method", "class") and leaf.signature:
        crumbs.append(leaf.signature)
    elif leaf.symbol_kind == "merged":
        crumbs.append(leaf.symbol)
    elif leaf.symbol_kind == "module":
        crumbs.append("module-level code")
    first = "# " + SEP.join(crumbs)
    if leaf.part is not None:
        first += f" (part {leaf.part[0]}/{leaf.part[1]})"
    lines = [first]
    imps = relevant_imports(leaf.code, imports)
    if imps:
        lines.append("# uses: " + "; ".join(imps))
    return "\n".join(lines)

def make_leaves(
    parsed: ParsedFile, source: str, tok: tiktoken.Encoding, cfg: ChunkConfig
) -> list[Leaf]:
    """Leaf chunks for one parsed file, in source order."""
    lines = source.splitlines()
    units = _units(parsed, lines)
    split: list[Leaf] = []
    for u in units:
        split.extend(_split(u, tok, cfg.max_symbol_tokens))
    leaves = _merge(split, tok, cfg)
    for leaf in leaves:
        leaf.text = (
            f"{header(leaf, parsed.imports)}\n{leaf.code}" if cfg.contextual_header else leaf.code
        )
    return leaves

@code_app.callback()
def _main() -> None:
    # Node text contains non-ASCII (e.g. "›"); never crash on a narrow console encoding.
    for stream in (sys.stdout, sys.stderr):
        reconfigure = getattr(stream, "reconfigure", None)
        if reconfigure is not None:
            with contextlib.suppress(ValueError, OSError):
                reconfigure(errors="replace")

def _setup_logging(verbose: bool) -> None:
    from ..settings import get_settings

    level = "DEBUG" if verbose else get_settings().log_level
    logging.basicConfig(
        level=level, format="%(asctime)s %(levelname)s %(name)s: %(message)s", stream=sys.stderr
    )
    for noisy in ("httpx", "google_genai", "numba", "urllib3", "mcp"):
        logging.getLogger(noisy).setLevel(logging.WARNING)

def _progress(ev: dict[str, Any]) -> None:
    stage = ev.get("stage")
    show = {
        "parsing": ev.get("done") == ev.get("total"),
        "embedding": bool(ev.get("total")),
        "summarizing": bool(ev.get("total")) and ev.get("done") in (0, ev.get("total")),
    }.get(str(stage), True)
    if show:
        typer.echo(f"  {ev}", err=True)

def _load(index: Path):
    from .index import CodeIndex

    return CodeIndex.load(index)

@code_app.command()
def update(index: IndexDir, verbose: VerboseOpt = False) -> None:
    """Re-index files changed since the index was built (git diff or content hashes)."""
    _setup_logging(verbose)
    idx = _load(index)
    result = idx.update(progress=_progress)
    if result["changed_files"]:
        idx.save(index)
    typer.echo(
        f"Changed files: {len(result['changed_files'])}; re-embedded {result['reembedded']}; "
        f"re-summarized {result['resummarized']}"
    )
    for f in result["changed_files"]:
        typer.echo(f"  {f}")

@code_app.command()
def ask(
    index: IndexDir,
    question: Annotated[str, typer.Argument()],
    k: Annotated[int, typer.Option("--top-k", "-k")] = 10,
    show_context: Annotated[bool, typer.Option(help="List the retrieved nodes first.")] = False,
    as_json: JsonOpt = False,
    verbose: VerboseOpt = False,
) -> None:
    """Answer a question about the codebase with path:line citations."""
    _setup_logging(verbose)
    from .types import CodeAnswer

    idx = _load(index)
    if as_json:
        typer.echo(json.dumps(idx.ask(question, k).to_dict(), indent=2))
        return
    final: CodeAnswer | None = None
    for piece in idx.stream_ask(question, k):
        if isinstance(piece, CodeAnswer):
            final = piece
        else:
            typer.echo(piece, nl=False)
    typer.echo("")
    if final is not None and (show_context or final.citations):
        typer.echo("\nSources:")
        for c in final.citations:
            typer.echo(f"  - {c.location} ({c.kind} {c.symbol})")

@code_app.command("serve-mcp")
def serve_mcp(index: IndexDir, verbose: VerboseOpt = False) -> None:
    """Serve the index as an MCP server over stdio (for Claude Code, IDEs, ...)."""
    _setup_logging(verbose)
    from .mcp_server import serve

    serve(index)

@classmethod
def from_yaml(cls, path: str | Path) -> CodeConfig:
    data = yaml.safe_load(Path(path).read_text(encoding="utf-8")) or {}
    return cls.model_validate(data)

def to_yaml(self, path: str | Path | None = None) -> str:
    text = yaml.safe_dump(self.model_dump(mode="json"), sort_keys=False)
    if path is not None:
        Path(path).write_text(text, encoding="utf-8")
    return text

def fingerprint(self) -> str:
    blob = json.dumps(self.model_dump(mode="json"), sort_keys=True).encode()
    return hashlib.sha256(blob).hexdigest()[:12]

@dataclass(frozen=True)
class SymEdge:
    src: SymKey
    dst: SymKey
    kind: str  # "imports" | "calls" | "inherits"

@dataclass
class _Binding:
    path: str | None  # target file (None: external)
    qualname: str | None  # target symbol in that file (None: the module itself)
    module: str

def __init__(
    self, parsed: dict[str, ParsedFile], extractors: dict[str, LanguageExtractor]
) -> None:
    self.parsed = parsed
    self.module_to_path: dict[str, str] = {}
    self.path_to_module: dict[str, str] = {}
    for path in parsed:
        ex = next((e for ext, e in extractors.items() if path.lower().endswith(ext)), None)
        mod = ex.module_name(path) if ex else None
        if mod:
            self.module_to_path.setdefault(mod, path)
            self.path_to_module[path] = mod
    self.symbols: dict[str, dict[str, Symbol]] = {
        path: {s.qualname: s for s in pf.symbols} for path, pf in parsed.items()
    }
    self.by_name: dict[str, list[tuple[str, Symbol]]] = defaultdict(list)
    for path, syms in self.symbols.items():
        for s in syms.values():
            self.by_name[s.name].append((path, s))
    self._bindings: dict[str, dict[str, _Binding]] = {}

def _resolve_module(self, name: str) -> str | None:
    if name in self.module_to_path:
        return self.module_to_path[name]
    hits = [p for m, p in self.module_to_path.items() if m.endswith("." + name)]
    return hits[0] if len(hits) == 1 else None

def _absolute(self, path: str, module: str, level: int) -> str:
    if level == 0:
        return module
    own = self.path_to_module.get(path, "")
    is_pkg = path.endswith(("__init__.py", "__init__.pyi"))
    parts = own.split(".") if own else []
    if not is_pkg:
        parts = parts[:-1]
    if level > 1:
        parts = parts[: max(0, len(parts) - (level - 1))]
    base = ".".join(parts)
    return f"{base}.{module}" if base and module else (base or module)

def bindings(self, path: str, _depth: int = 0) -> dict[str, _Binding]:
    if path in self._bindings:
        return self._bindings[path]
    out: dict[str, _Binding] = {}
    self._bindings[path] = out  # guards against import cycles
    for imp in self.parsed[path].imports:
        mod = self._absolute(path, imp.module, imp.level)
        if imp.name is None:  # import a.b [as x]
            if imp.alias:
                out[imp.alias] = _Binding(self._resolve_module(mod), None, mod)
            else:
                top = mod.split(".")[0]
                out[top] = _Binding(self._resolve_module(top), None, top)
            continue
        if imp.name == "*":
            target = self._resolve_module(mod)
            if target and _depth < 3:
                for qual, s in self.symbols.get(target, {}).items():
                    if s.parent is None:
                        out.setdefault(qual, _Binding(target, qual, mod))
            continue
        bound = imp.alias or imp.name
        sub = self._resolve_module(f"{mod}.{imp.name}") if mod else None
        if sub is not None:
            out[bound] = _Binding(sub, None, f"{mod}.{imp.name}")
            continue
        target = self._resolve_module(mod) if mod else None
        out[bound] = self._follow(target, imp.name, mod, _depth)
    return out

def _follow(self, target: str | None, name: str, mod: str, depth: int) -> _Binding:
    """Resolve ``name`` in file ``target``, following re-exports a few hops."""
    if target is None:
        return _Binding(None, None, mod)
    if name in self.symbols.get(target, {}):
        return _Binding(target, name, mod)
    if depth < 3:
        b = self.bindings(target, depth + 1).get(name)
        if b is not None and b.path is not None:
            return b
    return _Binding(target, None, mod)

def _class_of(self, path: str, sym: Symbol) -> Symbol | None:
    if sym.kind == "class":
        return sym
    if sym.parent:
        return self.symbols[path].get(sym.parent)
    return None

def _resolve_class_ref(self, path: str, ref: str) -> SymKey | None:
    """Resolve a base-class / class reference like ``Base`` or ``models.Base``."""
    key = self._resolve_name(path, ref)
    if key is None:
        return None
    p, q = key
    if q is not None and p is not None and self.symbols[p][q].kind == "class":
        return key
    return None

def _method_in(
    self, path: str, cls: Symbol, name: str, seen: set | None = None
) -> SymKey | None:
    seen = seen or set()
    if (path, cls.qualname) in seen:
        return None
    seen.add((path, cls.qualname))
    qual = f"{cls.qualname}.{name}"
    if qual in self.symbols[path]:
        return (path, qual)
    for base in cls.bases:
        key = self._resolve_class_ref(path, base)
        if key is None or key[1] is None:
            continue
        found = self._method_in(key[0], self.symbols[key[0]][key[1]], name, seen)
        if found:
            return found
    return None

def _resolve_name(self, path: str, ref: str) -> SymKey | None:
    parts = ref.split(".")
    head, rest = parts[0], parts[1:]
    syms = self.symbols[path]
    # Same-file top-level symbol.
    if head in syms and syms[head].parent is None:
        return self._descend(path, head, rest)
    b = self.bindings(path).get(head)
    if b is not None and b.path is not None:
        if b.qualname is not None:
            return self._descend(b.path, b.qualname, rest)
        return self._in_module(b.module, b.path, rest)
    if b is not None or rest:
        return None
    # Repo-wide unique top-level name.
    cands = [(p, s) for p, s in self.by_name.get(head, []) if s.parent is None]
    if len(cands) == 1:
        return (cands[0][0], cands[0][1].qualname)
    return None

def _in_module(self, module: str, path: str, rest: list[str]) -> SymKey | None:
    if not rest:
        return (path, None)
    sub = self._resolve_module(f"{module}.{rest[0]}")
    if sub is not None:
        return self._in_module(f"{module}.{rest[0]}", sub, rest[1:])
    if rest[0] in self.symbols.get(path, {}):
        return self._descend(path, rest[0], rest[1:])
    b = self.bindings(path).get(rest[0])
    if b is not None and b.path is not None and b.qualname is not None:
        return self._descend(b.path, b.qualname, rest[1:])
    return None

def _descend(self, path: str, qual: str, rest: list[str]) -> SymKey | None:
    if not rest:
        return (path, qual)
    sym = self.symbols[path].get(qual)
    if sym is None or sym.kind != "class":
        return None
    found = self._method_in(path, sym, rest[0])
    if found and len(rest) == 1:
        return found
    return None

def resolve_call(self, path: str, sym: Symbol, callee: str) -> SymKey | None:
    parts = callee.split(".")
    cls = self._class_of(path, sym)
    if parts[0] in ("self", "cls") and len(parts) == 2 and cls is not None:
        return self._method_in(path, cls, parts[1])
    if parts[0] == "super" and len(parts) == 2 and cls is not None:
        for base in cls.bases:
            key = self._resolve_class_ref(path, base)
            if key and key[1]:
                found = self._method_in(key[0], self.symbols[key[0]][key[1]], parts[1])
                if found:
                    return found
        return None
    key = self._resolve_name(path, callee)
    if key is not None:
        return key
    # obj.method(): link only when the method name is unique in the repo.
    if len(parts) == 2 and parts[0] not in ("self", "cls", "super"):
        name = parts[1]
        if name in _GENERIC_METHODS or name.startswith("__"):
            return None
        cands = [(p, s) for p, s in self.by_name.get(name, []) if s.kind == "method"]
        if len(cands) == 1:
            return (cands[0][0], cands[0][1].qualname)
    return None

def edges(self) -> list[SymEdge]:
    out: set[SymEdge] = set()
    for path, pf in self.parsed.items():
        for b in self.bindings(path).values():
            if b.path is not None and b.path != path:
                out.add(SymEdge((path, None), (b.path, None), "imports"))
        for sym in pf.symbols:
            src: SymKey = (path, sym.qualname)
            for callee in sym.calls:
                dst = self.resolve_call(path, sym, callee)
                if dst is not None and dst != src and dst[1] is not None:
                    out.add(SymEdge(src, dst, "calls"))
            if sym.kind == "class":
                for base in sym.bases:
                    dst2 = self._resolve_class_ref(path, base)
                    if dst2 is not None and dst2 != src:
                        out.add(SymEdge(src, dst2, "inherits"))
    return sorted(
        out, key=lambda e: (e.kind, e.src[0], e.src[1] or "", e.dst[0], e.dst[1] or "")
    )

def _write_json(path: Path, data: Any) -> None:
    fd, tmp = tempfile.mkstemp(prefix=".tmp-", dir=path.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump(data, fh, ensure_ascii=False)
        os.replace(tmp, path)
    except BaseException:
        Path(tmp).unlink(missing_ok=True)
        raise

def _scan(
    self, progress: ProgressCallback, reuse_files: dict[str, dict[str, Any]] | None
) -> tuple[dict[str, ParsedFile], dict[str, str], dict[str, dict[str, Any]], list[str]]:
    """Read and parse the repo. Files whose hash is unchanged reuse their stored parse."""
    extractors = self._extractors()
    paths = discover_files(self.repo_path, self.config.ingest, extractors.keys())
    parsed: dict[str, ParsedFile] = {}
    sources: dict[str, str] = {}
    records: dict[str, dict[str, Any]] = {}
    changed: list[str] = []
    total = len(paths)
    progress({"stage": "parsing", "done": 0, "total": total})
    for i, rel in enumerate(paths):
        data = read_source(self.repo_path, rel, self.config.ingest)
        if data is None:
            continue
        sha = sha256_bytes(data)
        prev = (reuse_files or {}).get(rel)
        text = data.decode("utf-8", errors="replace")
        if prev is not None and prev["sha"] == sha:
            pf = ParsedFile.from_dict(prev["parsed"])
        else:
            ex = extractor_for(rel, extractors)
            if ex is None:
                continue
            try:
                pf = ex.parse(data, rel)
            except Exception as exc:  # pragma: no cover - parser bugs
                logger.warning("failed to parse %s: %s", rel, exc)
                continue
            changed.append(rel)
        parsed[rel] = pf
        sources[rel] = text
        records[rel] = {"sha": sha, "language": pf.language, "parsed": pf.to_dict()}
        if (i + 1) % 50 == 0 or i + 1 == total:
            progress({"stage": "parsing", "done": i + 1, "total": total})
    return parsed, sources, records, changed

def _readme(self) -> str | None:
    for name in README_NAMES:
        p = self.repo_path / name
        if p.is_file():
            try:
                return p.read_text(encoding="utf-8", errors="replace")
            except OSError:
                return None
    return None

def _symbol_nodes(self) -> dict[SymKey, int]:
    """Map ``(path, qualname)`` (and ``(path, None)`` for files) to node indices."""
    out: dict[SymKey, int] = {}
    for n in sorted(self.tree.all_nodes.values(), key=lambda n: n.index):
        m = n.metadata
        kind = m.get("kind")
        if kind == "file":
            out[(m["path"], None)] = n.index
        elif kind == "class":
            out[(m["path"], m["symbol"])] = n.index
    for n in sorted(self.tree.leaf_nodes.values(), key=lambda n: n.index):
        m = n.metadata
        for q in m.get("symbols", []):
            out.setdefault((m["path"], q), n.index)
    return out

def _compute_edges(self, parsed: dict[str, ParsedFile]) -> list[CodeEdge]:
    sym_edges = CodeGraphBuilder(parsed, self._extractors()).edges()
    nodes = self._symbol_nodes()
    out: set[CodeEdge] = set()
    for e in sym_edges:
        src, dst = nodes.get(e.src), nodes.get(e.dst)
        if src is not None and dst is not None and src != dst:
            out.add(CodeEdge(src, dst, e.kind))
    return sorted(out, key=lambda e: (e.kind, e.src, e.dst))

@property
def searcher(self) -> CodeSearcher:
    if self._searcher is None:
        emb = self.models.embedding if self.config.retrieval.dense else None
        self._searcher = CodeSearcher(self.tree, self.edges, emb, self.config.retrieval)
    return self._searcher

def search(self, query: str, k: int = 10, **options: Any) -> list[CodeHit]:
    """Hybrid search. ``options`` override retrieval settings for this call
    (``dense``, ``bm25``, ``graph_expansion``, ``descend``, ``routing``, ``kinds``)."""
    return self.searcher.search(query, k, **options)

def _ask_hits(self, question: str, k: int) -> list[CodeHit]:
    hits = self.search(question, k)
    # Graph context: add the callers / callees of the top symbol hits if budget allows.
    seen = {h.node_index for h in hits}
    extra: list[CodeHit] = []
    if self.config.retrieval.graph_expansion:
        for h in hits[:3]:
            if h.kind not in ("symbol", "class"):
                continue
            nb = self.searcher.neighbors(h.node_index)
            for idx in (nb["callees"] + nb["callers"])[:2]:
                if idx not in seen:
                    seen.add(idx)
                    extra.append(to_hit(self.tree.all_nodes[idx], 0.0))
    return hits + extra

def ask(self, question: str, k: int = 10) -> CodeAnswer:
    context, used = self._context(self._ask_hits(question, k))
    answer = self.models.qa.answer_question(context, question)
    return CodeAnswer(answer=answer, citations=used)

def symbol(self, node_index: int) -> dict[str, Any]:
    """A node with its children, parents, callers and callees (as :class:`CodeHit`)."""
    if node_index not in self.tree.all_nodes:
        raise KeyError(f"no node {node_index}")
    node = self.tree.all_nodes[node_index]
    callers, callees = self._call_neighbors(node_index)
    return {
        "hit": self.node_hit(node_index),
        "children": [self.node_hit(c) for c in sorted(node.children)],
        "parents": [self.node_hit(p) for p in self.searcher.parents.get(node_index, [])],
        "callers": [self.node_hit(i) for i in callers],
        "callees": [self.node_hit(i) for i in callees],
    }

def _call_neighbors(self, node_index: int) -> tuple[list[int], list[int]]:
    node = self.tree.all_nodes[node_index]
    kind = node_kind(node)
    s = self.searcher
    if kind == "file":
        imports_out = [e.dst for e in self.edges if e.kind == "imports" and e.src == node_index]
        imports_in = [e.src for e in self.edges if e.kind == "imports" and e.dst == node_index]
        return imports_in, imports_out
    members = {node_index}
    if kind == "class":
        members |= set(node.children)
    callers = [c for m in members for c in s.callers.get(m, []) if c not in members]
    callees = [c for m in members for c in s.callees.get(m, []) if c not in members]
    return list(dict.fromkeys(callers)), list(dict.fromkeys(callees))

def graph(self, kinds: Iterable[str] = ("calls", "imports", "inherits")) -> list[CodeEdge]:
    wanted = set(kinds)
    return [e for e in self.edges if e.kind in wanted]

def module_node(self, path: str) -> int | None:
    """Node index of the file or directory ``path`` (or the repo for ``.``/empty)."""
    path = path.strip().strip("/").replace("\\", "/")
    for n in self.tree.all_nodes.values():
        m = n.metadata
        if path in ("", ".") and m.get("kind") == "repo":
            return n.index
        if m.get("kind") in ("file", "dir") and m.get("path") == path:
            return n.index
    # Accept a dotted module name, e.g. "raptor.code.index".
    dotted = path.replace(".", "/")
    for cand in (f"{dotted}.py", f"{dotted}/__init__.py", dotted):
        for n in self.tree.all_nodes.values():
            m = n.metadata
            if m.get("kind") in ("file", "dir") and (
                m.get("path") == cand or str(m.get("path", "")).endswith("/" + cand)
            ):
                return n.index
    return None

def outline(self, max_depth: int = 4) -> list[tuple[int, CodeHit]]:
    """``(depth, hit)`` rows of the structural hierarchy, repo first (for printing)."""
    repo = next(n for n in self.tree.root_nodes.values() if n.metadata.get("kind") == "repo")
    rows: list[tuple[int, CodeHit]] = []

    def visit(idx: int, depth: int) -> None:
        node = self.tree.all_nodes[idx]
        rows.append((depth, self.node_hit(idx)))
        if depth >= max_depth:
            return
        kids = sorted(
            node.children,
            key=lambda c: (
                self.tree.all_nodes[c].metadata.get("kind") != "dir",
                str(self.tree.all_nodes[c].metadata.get("path", "")),
                self.tree.all_nodes[c].metadata.get("start_line", 0),
            ),
        )
        for c in kids:
            visit(c, depth + 1)

    visit(repo.index, 0)
    for n in sorted(self.tree.root_nodes.values(), key=lambda n: n.index):
        if n.metadata.get("kind") == "concept":
            rows.append((0, self.node_hit(n.index)))
    return rows

def stats(self) -> dict[str, Any]:
    counts: dict[str, int] = {}
    for n in self.tree.all_nodes.values():
        k = node_kind(n)
        counts[k] = counts.get(k, 0) + 1
    edges: dict[str, int] = {}
    for e in self.edges:
        edges[e.kind] = edges.get(e.kind, 0) + 1
    return {
        "repo_path": str(self.repo_path),
        "files": len(self._files),
        "nodes": counts,
        "edges": edges,
        "layers": self.tree.num_layers + 1,
        "git_commit": self.git_commit,
    }

def is_generated(path: str, data: bytes) -> bool:
    if path.endswith(GENERATED_SUFFIXES):
        return True
    head = data[:600].decode("utf-8", errors="ignore").lower()
    return any(m in head for m in GENERATED_MARKERS)

def _skip_by_dir(rel: str) -> bool:
    parts = rel.split("/")[:-1]
    return any(p in SKIP_DIRS or p.endswith(".egg-info") for p in parts)

def _pathspec(patterns: Iterable[str]):
    import pathspec

    try:  # pathspec >= 0.12.2 names the git-compatible flavour "gitignore"
        return pathspec.PathSpec.from_lines("gitignore", list(patterns))
    except (KeyError, LookupError):
        return pathspec.PathSpec.from_lines("gitwildmatch", list(patterns))

def _git_files(root: Path) -> list[str] | None:
    git = shutil.which("git")
    if git is None or not (root / ".git").exists():
        return None
    try:
        out = subprocess.run(
            [git, "-C", str(root), "ls-files", "-z", "--cached", "--others", "--exclude-standard"],
            capture_output=True,
            check=True,
            timeout=60,
        ).stdout
    except (subprocess.SubprocessError, OSError) as exc:
        logger.warning("git ls-files failed (%s); falling back to walking the tree", exc)
        return None
    return sorted({p for p in out.decode("utf-8", errors="replace").split("\0") if p})

def _walk_files(root: Path) -> list[str]:
    """Walk ``root`` honouring every ``.gitignore`` found on the way down."""
    specs: list[tuple[str, object]] = []
    out: list[str] = []
    for dirpath, dirnames, filenames in os.walk(root):
        rel_dir = Path(dirpath).relative_to(root).as_posix()
        rel_dir = "" if rel_dir == "." else rel_dir
        if ".gitignore" in filenames:
            lines = (Path(dirpath) / ".gitignore").read_text(encoding="utf-8", errors="ignore")
            specs.append((rel_dir, _pathspec(lines.splitlines())))

        def ignored(rel: str, is_dir: bool) -> bool:
            for base, spec in specs:
                if base and not rel.startswith(base + "/"):
                    continue
                sub = rel[len(base) + 1 :] if base else rel
                if spec.match_file(sub + ("/" if is_dir else "")):  # type: ignore[attr-defined]
                    return True
            return False

        keep = []
        for d in sorted(dirnames):
            rel = f"{rel_dir}/{d}" if rel_dir else d
            if d in SKIP_DIRS or d.endswith(".egg-info") or ignored(rel, True):
                continue
            keep.append(d)
        dirnames[:] = keep
        for f in sorted(filenames):
            rel = f"{rel_dir}/{f}" if rel_dir else f
            if not ignored(rel, False):
                out.append(rel)
    return sorted(out)

def read_source(root: str | Path, rel: str, cfg: IngestConfig) -> bytes | None:
    """File contents, or ``None`` if the file is missing, too big, binary or generated."""
    path = Path(root) / rel
    try:
        if path.stat().st_size > cfg.max_file_bytes:
            logger.info("skipping %s: larger than %d bytes", rel, cfg.max_file_bytes)
            return None
        data = path.read_bytes()
    except OSError:
        return None
    if is_binary(data) or is_generated(rel, data):
        return None
    return data

def git_head(root: str | Path) -> str | None:
    git = shutil.which("git")
    if git is None or not (Path(root) / ".git").exists():
        return None
    try:
        out = subprocess.run(
            [git, "-C", str(root), "rev-parse", "HEAD"], capture_output=True, check=True, timeout=30
        ).stdout
    except (subprocess.SubprocessError, OSError):
        return None
    return out.decode().strip() or None

def make_extractors(languages: list[str]) -> dict[str, LanguageExtractor]:
    """Instantiate the extractors for ``languages``; returns ``{extension: extractor}``."""
    out: dict[str, LanguageExtractor] = {}
    for name in languages:
        ex = EXTRACTORS.create(name)
        for ext in ex.extensions:
            out[ext] = ex
    return out

def extractor_for(path: str, extractors: dict[str, LanguageExtractor]) -> LanguageExtractor | None:
    lower = path.lower()
    for ext, ex in extractors.items():
        if lower.endswith(ext):
            return ex
    return None

@property
def bound_name(self) -> str:
    """The local name this import introduces."""
    if self.alias:
        return self.alias
    if self.name:
        return self.name
    return self.module.split(".")[0]

@classmethod
def from_dict(cls, data: dict[str, Any]) -> Symbol:
    return cls(**data)

def to_dict(self) -> dict[str, Any]:
    return {
        "path": self.path,
        "language": self.language,
        "module_docstring": self.module_docstring,
        "imports": [asdict(i) for i in self.imports],
        "symbols": [s.to_dict() for s in self.symbols],
        "module_code": [list(r) for r in self.module_code],
        "num_lines": self.num_lines,
    }

@classmethod
def from_dict(cls, data: dict[str, Any]) -> ParsedFile:
    return cls(
        path=data["path"],
        language=data["language"],
        module_docstring=data.get("module_docstring", ""),
        imports=[ImportRef(**i) for i in data.get("imports", [])],
        symbols=[Symbol.from_dict(s) for s in data.get("symbols", [])],
        module_code=[(int(a), int(b)) for a, b in data.get("module_code", [])],
        num_lines=int(data.get("num_lines", 0)),
    )

class LanguageExtractor(ABC):
    name: str = ""
    extensions: tuple[str, ...] = ()

def module_name(self, path: str) -> str | None:
    """Dotted module name for ``path`` (used to resolve imports), or ``None``."""
    return None

def _load_language() -> Any:
    try:
        import tree_sitter_python
        from tree_sitter import Language

        return Language(tree_sitter_python.language())
    except ImportError:
        pass
    try:
        from tree_sitter_language_pack import get_language

        return get_language("python")
    except ImportError as exc:  # pragma: no cover - depends on extras
        raise ImportError(
            "Code indexing needs tree-sitter: `pip install raptor-code[code]`"
        ) from exc

def _parser() -> Any:
    parser = getattr(_LOCAL, "parser", None)
    if parser is None:
        from tree_sitter import Parser

        parser = _LOCAL.parser = Parser(_load_language())
    return parser

def _string_value(node: Any) -> str:
    raw = _text(node)
    try:
        value = ast.literal_eval(raw)
        if isinstance(value, bytes):
            value = value.decode("utf-8", errors="replace")
        return str(value)
    except (ValueError, SyntaxError):
        return raw.strip("rRbBuUfF").strip("'\"")

def _docstring(body: Any) -> str:
    """Docstring of a ``block``/``module`` node, if its first statement is a string."""
    if body is None:
        return ""
    for child in body.named_children:
        if child.type == "comment":
            continue
        if child.type == "expression_statement" and child.named_children:
            first = child.named_children[0]
            if first.type in ("string", "concatenated_string"):
                return _clean_doc(_string_value(first))
        return ""
    return ""

def _clean_doc(doc: str) -> str:
    import inspect

    return inspect.cleandoc(doc).strip()

def _callee(func: Any) -> str | None:
    text = _text(func)
    if func.type == "attribute":
        obj = func.child_by_field_name("object")
        attr = func.child_by_field_name("attribute")
        if obj is not None and obj.type == "call" and attr is not None:
            inner = obj.child_by_field_name("function")
            if inner is not None and _text(inner) == "super":
                return f"super.{_text(attr)}"
    text = re.sub(r"\s+", "", text)
    return text if _SIMPLE_CALLEE.match(text) else None

def _collect_calls(node: Any, out: list[str], *, skip_defs: bool) -> None:
    stack = [node]
    while stack:
        cur = stack.pop()
        if cur.type == "call":
            func = cur.child_by_field_name("function")
            if func is not None:
                name = _callee(func)
                if name:
                    out.append(name)
        for child in cur.children:
            if skip_defs and child.type in (
                "function_definition",
                "class_definition",
                "decorated_definition",
            ):
                continue
            stack.append(child)

@EXTRACTORS.register("python")
class PythonExtractor(LanguageExtractor):
    name = "python"
    extensions = (".py", ".pyi")
    # ----------------------------------------------------------------- helpers

def module_name(self, path: str) -> str | None:
    parts = path.replace("\\", "/").split("/")
    if not parts[-1].endswith((".py", ".pyi")):
        return None
    parts[-1] = parts[-1].rsplit(".", 1)[0]
    if parts[-1] == "__init__":
        parts = parts[:-1]
    while len(parts) > 1 and parts[0] in _SOURCE_ROOTS:
        parts = parts[1:]
    return ".".join(parts) if parts else None

def parse(self, source: bytes, path: str) -> ParsedFile:
    tree = _parser().parse(source)
    root = tree.root_node
    lines = source.decode("utf-8", errors="replace").splitlines()
    parsed = ParsedFile(path=path, language=self.name, num_lines=len(lines))
    parsed.module_docstring = _docstring(root)

    covered: list[tuple[int, int]] = []
    for child in root.named_children:
        if child.type in ("import_statement", "import_from_statement"):
            parsed.imports.extend(self._imports(child))
        elif child.type in ("if_statement", "try_statement"):
            # Guarded imports (try/except ImportError, TYPE_CHECKING) are common.
            for sub in _walk_types(child, ("import_statement", "import_from_statement")):
                parsed.imports.extend(self._imports(sub))
        definition, decorators, outer = _unwrap(child)
        if definition is None:
            continue
        if definition.type == "function_definition":
            parsed.symbols.append(
                self._function(definition, decorators, outer, source, lines, parent=None)
            )
            covered.append((_line(outer), _end_line(outer)))
        elif definition.type == "class_definition":
            parsed.symbols.extend(
                self._class(definition, decorators, outer, source, lines, prefix="")
            )
            covered.append((_line(outer), _end_line(outer)))

    parsed.module_code = _uncovered(len(lines), covered, lines)
    return parsed

def _imports(self, node: Any) -> list[ImportRef]:
    line = _line(node)
    text = re.sub(r"\s+", " ", _text(node)).strip()
    out: list[ImportRef] = []
    if node.type == "import_statement":
        for child in node.named_children:
            if child.type == "dotted_name":
                out.append(ImportRef(module=_text(child), line=line, text=text))
            elif child.type == "aliased_import":
                name = child.child_by_field_name("name")
                alias = child.child_by_field_name("alias")
                if name is not None:
                    out.append(
                        ImportRef(
                            module=_text(name),
                            alias=_text(alias) if alias is not None else None,
                            line=line,
                            text=text,
                        )
                    )
        return out
    # import_from_statement
    module_node = node.child_by_field_name("module_name")
    module, level = "", 0
    if module_node is not None:
        raw = _text(module_node)
        level = len(raw) - len(raw.lstrip("."))
        module = raw.lstrip(".")
    names = node.children_by_field_name("name")
    if not names and any(c.type == "wildcard_import" for c in node.children):
        out.append(ImportRef(module=module, name="*", level=level, line=line, text=text))
    for n in names:
        if n.type == "aliased_import":
            name = n.child_by_field_name("name")
            alias = n.child_by_field_name("alias")
            out.append(
                ImportRef(
                    module=module,
                    name=_text(name) if name is not None else None,
                    alias=_text(alias) if alias is not None else None,
                    level=level,
                    line=line,
                    text=text,
                )
            )
        else:
            out.append(
                ImportRef(module=module, name=_text(n), level=level, line=line, text=text)
            )
    return out

def _walk_types(node: Any, types: tuple[str, ...]) -> list[Any]:
    out = []
    stack = [node]
    while stack:
        cur = stack.pop()
        if cur.type in types:
            out.append(cur)
            continue
        if cur.type in ("function_definition", "class_definition"):
            continue
        stack.extend(cur.children)
    return out

def _uncovered(
    num_lines: int, covered: list[tuple[int, int]], lines: list[str]
) -> list[tuple[int, int]]:
    """Contiguous non-blank line ranges outside ``covered``."""
    mask = [False] * (num_lines + 2)
    for a, b in covered:
        for i in range(a, min(b, num_lines) + 1):
            mask[i] = True
    ranges: list[tuple[int, int]] = []
    start: int | None = None
    for i in range(1, num_lines + 1):
        free = not mask[i]
        if free and start is None:
            start = i
        if not free and start is not None:
            ranges.append((start, i - 1))
            start = None
    if start is not None:
        ranges.append((start, num_lines))
    out = []
    for a, b in ranges:
        while a <= b and not lines[a - 1].strip():
            a += 1
        while b >= a and not lines[b - 1].strip():
            b -= 1
        if a <= b:
            out.append((a, b))
    return out

def split_identifier(word: str) -> list[str]:
    """``getHTTPResponse_code`` -> ``["get", "http", "response", "code"]``."""
    out: list[str] = []
    for piece in word.split("_"):
        if piece:
            out.extend(m.lower() for m in _CAMEL.findall(piece))
    return out

def tokenize(text: str) -> list[str]:
    """Identifier-aware tokens: each identifier, lowercased, plus its camel/snake parts."""
    tokens: list[str] = []
    for word in _IDENT.findall(text):
        low = word.lower()
        parts = split_identifier(word)
        if len(parts) > 1 or (parts and parts[0] != low):
            tokens.append(low)
            tokens.extend(p for p in parts if p not in STOPWORDS and len(p) > 1)
        elif low not in STOPWORDS and len(low) > 1:
            tokens.append(low)
    return tokens

def __init__(self, docs: Sequence[Sequence[str]], k1: float = 1.2, b: float = 0.75) -> None:
    self.k1, self.b = k1, b
    self.n = len(docs)
    self.lengths = [len(d) for d in docs]
    self.avgdl = (sum(self.lengths) / self.n) if self.n else 0.0
    self.postings: dict[str, list[tuple[int, int]]] = {}
    for i, d in enumerate(docs):
        for term, tf in Counter(d).items():
            self.postings.setdefault(term, []).append((i, tf))
    self.idf = {
        t: math.log(1 + (self.n - len(p) + 0.5) / (len(p) + 0.5))
        for t, p in self.postings.items()
    }

def scores(self, query: Sequence[str]) -> dict[int, float]:
    out: dict[int, float] = {}
    if not self.n:
        return out
    for term, qtf in Counter(query).items():
        plist = self.postings.get(term)
        if not plist:
            continue
        idf = self.idf[term]
        for i, tf in plist:
            denom = tf + self.k1 * (1 - self.b + self.b * self.lengths[i] / (self.avgdl or 1))
            out[i] = out.get(i, 0.0) + qtf * idf * tf * (self.k1 + 1) / denom
    return out

def top(self, query: Sequence[str], k: int) -> list[tuple[int, float]]:
    s = self.scores(query)
    return sorted(s.items(), key=lambda kv: (-kv[1], kv[0]))[:k]

def _hit(h: CodeHit, *, text: bool = True, limit: int = TEXT_LIMIT) -> dict[str, Any]:
    d: dict[str, Any] = {
        "node": h.node_index,
        "kind": h.kind,
        "location": h.location,
        "symbol": h.symbol,
        "score": round(h.score, 5),
    }
    if text:
        d["text"] = h.text if len(h.text) <= limit else h.text[:limit] + "\n... (truncated)"
    return d

def _resolve(index: CodeIndex, symbol: str) -> tuple[int | None, list[CodeHit]]:
    """Node for ``symbol``: a node index, a (qualified) name or a ``path:line`` location."""
    s = symbol.strip()
    if s.isdigit() and int(s) in index.tree.all_nodes:
        return int(s), []
    if ":" in s and s.rsplit(":", 1)[1].split("-")[0].isdigit():
        path, line_s = s.rsplit(":", 1)
        line = int(line_s.split("-")[0])
        best: tuple[int, int] | None = None
        for n in index.tree.leaf_nodes.values():
            m = n.metadata
            if m.get("path") == path and m["start_line"] <= line <= m["end_line"]:
                span = m["end_line"] - m["start_line"]
                if best is None or span < best[0]:
                    best = (span, n.index)
        if best is not None:
            return best[1], []
    matches = index.find_symbol(s)
    if not matches:
        hits = index.search(s, k=5)
        return (hits[0].node_index if hits else None), hits[1:]
    # Prefer classes and whole symbols over parts / module code.
    matches.sort(key=lambda h: (h.kind not in ("class", "symbol"), h.kind != "class", h.layer))
    return matches[0].node_index, matches[1:]

def create_server(index: CodeIndex) -> Any:
    server = _server_class()("raptor-code", instructions=INSTRUCTIONS)

    @server.tool()
    def search_code(query: str, k: int = 10) -> dict[str, Any]:
        """Hybrid (lexical + semantic) search over the code index.

        Works for exact identifiers ("Session.request") and natural-language questions
        ("where are redirects handled"). Returns ranked nodes (symbols, classes, files,
        directories, concepts) with their location (path:start-end) and text.
        """
        hits = index.search(query, k=max(1, min(k, 50)))
        return {"query": query, "results": [_hit(h, limit=2000) for h in hits]}

    @server.tool()
    def ask_codebase(question: str, k: int = 8) -> dict[str, Any]:
        """Answer a question about the codebase, citing path:start-end locations."""
        ans = index.ask(question, k=max(1, min(k, 30)))
        return {
            "answer": ans.answer,
            "citations": [_hit(c, text=False) for c in ans.citations],
        }

    @server.tool()
    def get_symbol(symbol: str) -> dict[str, Any]:
        """Source and context of a symbol.

        ``symbol`` may be a name ("apply_discount"), a qualified name ("Cart.total"), a
        location ("shop/cart.py:32") or a node id. Returns its text, children, parents,
        callers and callees.
        """
        idx, others = _resolve(index, symbol)
        if idx is None:
            return {"error": f"no symbol matching {symbol!r}"}
        info = index.symbol(idx)
        return {
            "symbol": _hit(info["hit"]),
            "children": [_hit(h, text=False) for h in info["children"]],
            "parents": [_hit(h, text=False) for h in info["parents"]],
            "callers": [_hit(h, text=False) for h in info["callers"]],
            "callees": [_hit(h, text=False) for h in info["callees"]],
            "other_matches": [_hit(h, text=False) for h in others[:10]],
        }

    @server.tool()
    def explain_module(path: str) -> dict[str, Any]:
        """Summary of a file or directory (path like "raptor/code" or dotted module name),
        or of the whole repository for "."; lists its children."""
        idx = index.module_node(path)
        if idx is None:
            return {"error": f"no file or directory {path!r} in the index"}
        info = index.symbol(idx)
        return {
            "module": _hit(info["hit"]),
            "children": [_hit(h, text=False) for h in info["children"]],
            "concepts": [_hit(h, text=False) for h in info["parents"] if h.kind == "concept"],
        }

    @server.tool()
    def get_callers(symbol: str) -> dict[str, Any]:
        """Functions/methods that call ``symbol`` (best-effort static resolution).
        For a file, the files that import it."""
        idx, _ = _resolve(index, symbol)
        if idx is None:
            return {"error": f"no symbol matching {symbol!r}"}
        info = index.symbol(idx)
        return {
            "symbol": _hit(info["hit"], text=False),
            "callers": [_hit(h, limit=1500) for h in info["callers"]],
        }

    @server.tool()
    def get_callees(symbol: str) -> dict[str, Any]:
        """Functions/methods/classes that ``symbol`` calls (best-effort static resolution).
        For a file, the files it imports."""
        idx, _ = _resolve(index, symbol)
        if idx is None:
            return {"error": f"no symbol matching {symbol!r}"}
        info = index.symbol(idx)
        return {
            "symbol": _hit(info["hit"], text=False),
            "callees": [_hit(h, limit=1500) for h in info["callees"]],
        }

    return server

def answer_question(self, context: str, question: str) -> str:
    prompt = QA_TEMPLATE.format(context=context, question=question)
    return self._inner._generate(prompt, temperature=0.0)

def build_embedding_model(cfg: CodeModelsConfig) -> BaseEmbeddingModel:
    provider = cfg.embedding_provider or cfg.provider
    if provider == "gemini":
        from ..models.gemini import GeminiEmbeddingModel

        task = cfg.use_task_types
        return GeminiEmbeddingModel(
            cfg.embedding_model,
            document_task_type=cfg.document_task_type if task else None,
            query_task_type=cfg.query_task_type if task else None,
            batch_size=cfg.embed_batch_size,
        )
    if provider == "local":
        from ..models.local import SBertEmbeddingModel, resolve_local_embedding

        hub_id, q_prefix, d_prefix = resolve_local_embedding(cfg.embedding_model)
        return SBertEmbeddingModel(hub_id, query_prefix=q_prefix, document_prefix=d_prefix)
    from ..models.ollama import OllamaEmbeddingModel

    return OllamaEmbeddingModel(cfg.embedding_model)

def build_summarization_model(cfg: CodeModelsConfig) -> BaseSummarizationModel:
    provider = cfg.summary_provider or ("ollama" if cfg.provider == "ollama" else "gemini")
    model = cfg.summary_model or cfg.llm_model
    if provider == "ollama":
        return _OllamaPassthrough(model)
    from ..models.gemini import GeminiSummarizationModel

    return GeminiSummarizationModel(model, prompt_template=PASSTHROUGH_TEMPLATE)

def build_qa_model(cfg: CodeModelsConfig) -> BaseQAModel:
    if cfg.provider == "ollama":
        return _OllamaCodeQA(cfg.llm_model)
    from ..models.gemini import GeminiQAModel

    return GeminiQAModel(cfg.llm_model, prompt_template=QA_TEMPLATE)

def _cached(self, model: Any, kind: str) -> Any:
    settings = self._settings or get_settings()
    if not (self.cfg.cache and settings.cache_enabled):
        return model
    cache = open_cache(settings.cache_dir)
    wrapper = {
        "embedding": CachedEmbeddingModel,
        "summarization": CachedSummarizationModel,
        "qa": CachedQAModel,
    }[kind]
    return wrapper(model, cache)

@property
def embedding(self) -> BaseEmbeddingModel:
    if self._embedding is None:
        self._embedding = self._cached(build_embedding_model(self.cfg), "embedding")
    return self._embedding

@property
def summarization(self) -> BaseSummarizationModel:
    if self._summarization is None:
        self._summarization = self._cached(build_summarization_model(self.cfg), "summarization")
    return self._summarization

@property
def qa(self) -> BaseQAModel:
    if self._qa is None:
        self._qa = self._cached(build_qa_model(self.cfg), "qa")
    return self._qa

@dataclass
class _Ranked:
    index: int
    score: float

def __init__(
    self,
    tree: Tree,
    edges: list[CodeEdge],
    embedding_model: BaseEmbeddingModel | None,
    config: CodeRetrievalConfig,
) -> None:
    self.tree = tree
    self.cfg = config
    self.embedding_model = embedding_model
    self.ids = sorted(tree.all_nodes)
    self.pos = {idx: i for i, idx in enumerate(self.ids)}
    self._bm25: BM25 | None = None
    self.callees: dict[int, list[int]] = defaultdict(list)
    self.callers: dict[int, list[int]] = defaultdict(list)
    self.bases: dict[int, list[int]] = defaultdict(list)
    for e in edges:
        if e.kind == "calls":
            self.callees[e.src].append(e.dst)
            self.callers[e.dst].append(e.src)
        elif e.kind == "inherits":
            self.bases[e.src].append(e.dst)
    self.parents: dict[int, list[int]] = defaultdict(list)
    for n in tree.all_nodes.values():
        for c in n.children:
            self.parents[c].append(n.index)
    self.symbol_names = {
        str(n.metadata.get("symbol", "")).split(".")[-1].lower()
        for n in tree.all_nodes.values()
        if node_kind(n) in ("symbol", "class")
    }

@property
def bm25(self) -> BM25:
    if self._bm25 is None:
        self._bm25 = BM25([bm25_document(self.tree.all_nodes[i]) for i in self.ids])
    return self._bm25

def query_type(self, query: str) -> str:
    words = re.findall(r"[A-Za-z_]\w*", query)
    ident = bool(_IDENT_LIKE.search(query)) or (
        len(words) <= 4 and any(w.lower() in self.symbol_names for w in words)
    )
    broad = bool(_BROAD.search(query))
    if ident and broad:
        return "mixed"
    if ident:
        return "identifier"
    if broad:
        return "broad"
    return "neutral"

def search(
    self,
    query: str,
    k: int = 10,
    *,
    dense: bool | None = None,
    bm25: bool | None = None,
    graph_expansion: bool | None = None,
    descend: bool | None = None,
    routing: bool | None = None,
    kinds: tuple[str, ...] | None = None,
) -> list[CodeHit]:
    if not query or not query.strip():
        raise ValueError("query must be a non-empty string")
    cfg = self.cfg
    use_dense = cfg.dense if dense is None else dense
    use_bm25 = cfg.bm25 if bm25 is None else bm25
    use_graph = cfg.graph_expansion if graph_expansion is None else graph_expansion
    use_descend = cfg.descend if descend is None else descend
    use_routing = cfg.routing if routing is None else routing
    if self.embedding_model is None:
        use_dense = False
    if not (use_dense or use_bm25):
        raise ValueError("enable at least one of dense / bm25")
    allowed = {
        i
        for i in self.ids
        if node_kind(self.tree.all_nodes[i]) not in cfg.exclude_kinds
        and (kinds is None or node_kind(self.tree.all_nodes[i]) in kinds)
    }
    if not allowed:
        return []

    sims: np.ndarray | None = self.dense_scores(query) if use_dense else None
    fused: dict[int, float] = defaultdict(float)
    n_cand = max(cfg.candidates, k)
    if sims is not None:
        order = np.argsort(-sims)
        ranked = [self.ids[p] for p in order if self.ids[p] in allowed][:n_cand]
        for r, idx in enumerate(ranked):
            fused[idx] += 1.0 / (cfg.rrf_k + r + 1)
    if use_bm25:
        ranked_b = [
            i
            for i, _ in (
                (self.ids[p], s) for p, s in self.bm25.top(tokenize(query), n_cand * 3)
            )
            if i in allowed
        ][:n_cand]
        for r, idx in enumerate(ranked_b):
            fused[idx] += 1.0 / (cfg.rrf_k + r + 1)

    weights = ROUTING[self.query_type(query)] if use_routing else {}
    scores = {
        i: s * weights.get(node_kind(self.tree.all_nodes[i]), 1.0) for i, s in fused.items()
    }

    def sim_of(idx: int) -> float:
        return float(sims[self.pos[idx]]) if sims is not None else 0.0

    top = sorted(scores.items(), key=lambda kv: (-kv[1], kv[0]))[: max(k, 10)]
    decay = cfg.expansion_decay
    if use_descend:
        for idx, s in top:
            if node_kind(self.tree.all_nodes[idx]) in ("class", "file"):
                for leaf in self._best_leaves(idx, sim_of, allowed, 2):
                    scores[leaf] = max(scores.get(leaf, 0.0), s * decay)
    if use_graph:
        for idx, s in top[:k]:
            for nb in self._neighbors(idx, sim_of, allowed):
                scores[nb] = max(scores.get(nb, 0.0), s * decay * 0.95)

    final = sorted(scores.items(), key=lambda kv: (-kv[1], kv[0]))[:k]
    return [to_hit(self.tree.all_nodes[i], s) for i, s in final]

def _best_leaves(self, idx: int, sim_of, allowed: set[int], n: int) -> list[int]:
    leaves: list[int] = []
    stack = list(self.tree.all_nodes[idx].children)
    while stack:
        c = stack.pop()
        node = self.tree.all_nodes[c]
        if node.children:
            stack.extend(node.children)
        elif c in allowed:
            leaves.append(c)
    leaves.sort(key=lambda i: (-sim_of(i), i))
    return leaves[:n]

def neighbors(self, idx: int) -> dict[str, list[int]]:
    """Callers, callees, base classes and parent class of node ``idx``."""
    node = self.tree.all_nodes[idx]
    parent_class = [
        p for p in self.parents.get(idx, []) if node_kind(self.tree.all_nodes[p]) == "class"
    ]
    return {
        "callees": list(dict.fromkeys(self.callees.get(idx, []))),
        "callers": list(dict.fromkeys(self.callers.get(idx, []))),
        "bases": list(dict.fromkeys(self.bases.get(idx, []))),
        "parent_class": parent_class if node_kind(node) == "symbol" else [],
    }

@property
def location(self) -> str:
    """Citation string: ``path:start-end`` (or ``path/`` / the concept name)."""
    if self.kind in ("symbol", "class", "file") and self.start_line:
        return f"{self.path}:{self.start_line}-{self.end_line}"
    if self.kind == "dir":
        return f"{self.path}/"
    if self.kind == "repo":
        return "(repository overview)"
    return f"(concept: {self.symbol})"

