    return len(self.article.split())

def _parse(row: dict[str, Any]) -> QualityArticle:
    questions = [
        QualityQuestion(
            question_id=q.get("question_unique_id", f"{row['article_id']}-{i}"),
            question=q["question"],
            options=q["options"],
            gold_label=q.get("gold_label"),
            difficult=bool(q.get("difficult", 0)),
        )
        for i, q in enumerate(row.get("questions", []))
    ]
    return QualityArticle(
        set_id=row.get("set_unique_id", row["article_id"]),
        article_id=row["article_id"],
        title=row.get("title", ""),
        author=row.get("author", ""),
        article=row["article"],
        topic=row.get("topic", ""),
        questions=questions,
    )

def iter_quality(
    split: str = "dev", data_dir: str | Path = DEFAULT_DIR
) -> Iterator[QualityArticle]:
    path = Path(data_dir) / FILE_PATTERN.format(split=split)
    if not path.exists():
        raise FileNotFoundError(
            f"{path} not found. Run `python scripts/download_quality.py` first."
        )
    with path.open(encoding="utf-8") as fh:
        for line in fh:
            if line.strip():
                yield _parse(json.loads(line))

def load_quality(
    split: str = "dev", data_dir: str | Path = DEFAULT_DIR, limit: int | None = None
) -> list[QualityArticle]:
    out = []
    for i, art in enumerate(iter_quality(split, data_dir)):
        if limit is not None and i >= limit:
            break
        out.append(art)
    return out

def bootstrap_ci(
    correct: Sequence[bool],
    *,
    level: float = 0.95,
    samples: int = BOOTSTRAP_SAMPLES,
    seed: int = BOOTSTRAP_SEED,
) -> tuple[float, float]:
    """Percentile bootstrap CI for accuracy."""
    x = np.asarray(correct, dtype=np.float64)
    if len(x) == 0:
        return (float("nan"), float("nan"))
    rng = np.random.default_rng(seed)
    means = x[rng.integers(0, len(x), size=(samples, len(x)))].mean(axis=1)
    alpha = (1 - level) / 2
    return (float(np.quantile(means, alpha)), float(np.quantile(means, 1 - alpha)))

def paired_bootstrap_ci(
    a: Sequence[bool],
    b: Sequence[bool],
    *,
    level: float = 0.95,
    samples: int = BOOTSTRAP_SAMPLES,
    seed: int = BOOTSTRAP_SEED,
) -> tuple[float, float]:
    """CI for ``acc(b) - acc(a)`` over the same questions (resampling question pairs)."""
    d = np.asarray(b, dtype=np.float64) - np.asarray(a, dtype=np.float64)
    if len(d) == 0:
        return (float("nan"), float("nan"))
    rng = np.random.default_rng(seed)
    means = d[rng.integers(0, len(d), size=(samples, len(d)))].mean(axis=1)
    alpha = (1 - level) / 2
    return (float(np.quantile(means, alpha)), float(np.quantile(means, 1 - alpha)))

def mcnemar_exact(b: int, c: int) -> float:
    """Two-sided exact McNemar p-value from the discordant counts ``b`` and ``c``."""
    n = b + c
    if n == 0:
        return 1.0
    k = min(b, c)
    tail = sum(math.comb(n, i) for i in range(k + 1)) / 2**n
    return min(1.0, 2 * tail)

def layer_share(retrieved: Iterable[Iterable[dict[str, Any]]]) -> dict[str, float]:
    """Fraction of all retrieved nodes that came from each layer."""
    counts: dict[int, int] = {}
    for nodes in retrieved:
        for n in nodes:
            counts[int(n["layer"])] = counts.get(int(n["layer"]), 0) + 1
    total = sum(counts.values())
    return {str(k): counts[k] / total for k in sorted(counts)} if total else {}

def tree_stats(tree: Tree, token_count: Any = None) -> dict[str, float]:
    """Shape of one tree. ``layers`` counts the leaf layer too."""
    inner = [n for n in tree.all_nodes.values() if n.children]
    stats: dict[str, float] = {
        "layers": float(tree.num_layers + 1),
        "nodes": float(len(tree.all_nodes)),
        "leaves": float(len(tree.leaf_nodes)),
        "branching": float(np.mean([len(n.children) for n in inner])) if inner else 0.0,
    }
    if token_count is not None and inner:
        ratios = []
        for n in inner:
            child_tokens = sum(token_count(tree.all_nodes[c].text) for c in n.children)
            if child_tokens:
                ratios.append(token_count(n.text) / child_tokens)
        stats["compression"] = float(np.mean(ratios)) if ratios else 0.0
    return stats

def mean_tree_stats(per_tree: Sequence[dict[str, float]]) -> dict[str, float]:
    if not per_tree:
        return {"mean_layers": 0.0, "mean_nodes": 0.0, "mean_branching": 0.0}
    out = {
        "mean_layers": float(np.mean([t["layers"] for t in per_tree])),
        "mean_nodes": float(np.mean([t["nodes"] for t in per_tree])),
        "mean_branching": float(np.mean([t["branching"] for t in per_tree])),
        "mean_leaves": float(np.mean([t["leaves"] for t in per_tree])),
    }
    if all("compression" in t for t in per_tree):
        out["mean_compression"] = float(np.mean([t["compression"] for t in per_tree]))
    return out

def _baseline_for(run: dict[str, Any], runs: list[dict[str, Any]]) -> dict[str, Any] | None:
    name = run.get("baseline")
    if not name:
        return None
    same = [r for r in runs if r.get("name") == name and r.get("split") == run.get("split")]
    return same[-1] if same else None

def _verdict(cmp: dict[str, Any] | None) -> str:
    if cmp is None:
        return "baseline"
    if cmp["mcnemar_p"] < ALPHA:
        return "**better**" if cmp["delta"] > 0 else "**worse**"
    return "within noise"

def _pct(x: float | None, digits: int = 1) -> str:
    if x is None or (isinstance(x, float) and math.isnan(x)):
        return "-"
    return f"{100 * x:.{digits}f}"

def _setting(run: dict[str, Any]) -> str:
    f = run.get("factors", {})
    factor = run.get("factor", "")
    if factor in f:
        return f[factor]
    if factor == "method":
        return run.get("method", "")
    return " / ".join(f.get(k, "") for k in ("chunking", "clustering", "retrieval", "embedding"))

def _summary_share(run: dict[str, Any]) -> float:
    share = run.get("layer_share", {})
    return float(sum(v for k, v in share.items() if k != "0"))

def _order(runs: list[dict[str, Any]]) -> list[dict[str, Any]]:
    def key(r: dict[str, Any]) -> tuple[int, str]:
        f = r.get("factor") or ("baseline" if not r.get("baseline") else "combined")
        return (FACTOR_ORDER.index(f) if f in FACTOR_ORDER else len(FACTOR_ORDER), r["name"])

    return sorted(runs, key=key)

def _style(ax: Any) -> None:
    ax.set_facecolor(SURFACE)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    for side in ("left", "bottom"):
        ax.spines[side].set_color(GRID)
    ax.tick_params(colors=INK_2, labelsize=9)
    ax.grid(axis="x", color=GRID, linewidth=0.8)
    ax.set_axisbelow(True)

@classmethod
def from_yaml(cls, path: str | Path) -> ExperimentConfig:
    return cls.model_validate(yaml.safe_load(Path(path).read_text(encoding="utf-8")) or {})

def effective(self) -> RaptorConfig:
    """The RaptorConfig with this experiment's overrides applied."""
    cfg = self.raptor.model_copy(deep=True)
    if self.top_k is not None:
        cfg.retrieval.top_k = self.top_k
    if self.max_tokens is not None:
        cfg.retrieval.max_tokens = self.max_tokens
    if self.embedding:
        provider, _, model = self.embedding.partition(":")
        if not model or provider not in ("gemini", "local", "ollama"):
            raise ValueError(
                f"embedding must look like 'local:bge-small', got {self.embedding!r}"
            )
        cfg.models.embedding_provider = provider  # type: ignore[assignment]
        cfg.models.embedding_model = model
    return cfg

def run_id(self) -> str:
    """``<slug>-<hash>``: the hash covers everything that can change the results."""
    blob = json.dumps(
        {
            "method": self.method,
            "split": self.split,
            "config": self.effective().model_dump(mode="json"),
            "prompt": PROMPT_VERSION,
        },
        sort_keys=True,
    ).encode()
    slug = re.sub(r"[^a-z0-9]+", "-", self.name.lower()).strip("-")[:48] or "run"
    return f"{slug}-{hashlib.sha256(blob).hexdigest()[:8]}"

def factor_labels(cfg: RaptorConfig, method: str = "raptor") -> dict[str, str]:
    """Short human labels for the four sweep factors."""
    ch = cfg.chunking
    chunking = f"{ch.strategy}-{ch.max_tokens}" + (
        f"-o{ch.overlap_tokens}" if ch.overlap_tokens else ""
    )
    cl = cfg.clustering
    clustering = cl.strategy if method == "raptor" else "none"
    if cl.params and method == "raptor":
        clustering += "(" + ",".join(f"{k}={v}" for k, v in sorted(cl.params.items())) + ")"
    r = cfg.retrieval
    retrieval = (r.mode if method == "raptor" else "flat") + f"-k{r.top_k}"
    if r.max_tokens != 3500:
        retrieval += f"-t{r.max_tokens}"
    if r.hybrid:
        retrieval += "+bm25"
    if r.reranker:
        retrieval += "+rerank"
    if r.mmr_lambda is not None:
        retrieval += f"+mmr{r.mmr_lambda:g}"
    m = cfg.models
    embedding = m.embedding_model.split("/")[-1]
    if not m.use_task_types and (m.embedding_provider or m.provider) == "gemini":
        embedding += "-notask"
    return {
        "chunking": chunking,
        "clustering": clustering,
        "retrieval": retrieval,
        "embedding": embedding,
    }

@dataclass
class TreeRecord:
    tree: Tree
    build_seconds: float  # time of the original build (0 for cache-only rebuilds)
    built_now: bool
    stats: dict[str, float]

def __init__(self, root: str | Path = DEFAULT_TREES_DIR) -> None:
    self.root = Path(root)
    self._locks: dict[str, threading.Lock] = {}

@staticmethod
def key(cfg: RaptorConfig, method: str) -> str:
    if method == "flat":
        return "leaves-" + cfg.fingerprint(sections=LEAF_SECTIONS)
    return cfg.fingerprint(sections=TREE_SECTIONS)

def build_leaf_tree(text: str, cfg: RaptorConfig, models: ModelBundle) -> Tree:
    """Chunk and embed only (the flat-RAG index): a tree with just layer 0."""
    chunks = make_chunker(cfg.chunking, models.embedding).split(text)
    emb = models.embedding.embed_documents([c.text for c in chunks])
    key = cfg.builder.embedding_key
    leaves = [
        Node(c.text, i, set(), {key: emb[i]}, 0, {"start": c.start, "end": c.end})
        for i, c in enumerate(chunks)
    ]
    return Tree.from_layers(
        {0: leaves},
        metadata={"embedding_key": key, "embedding_model": models.embedding.model_id},
    )

@classmethod
def read(cls, models: ModelBundle, answerer: MCQAnswerer) -> Counters:
    emb = models.embedding.stats if isinstance(models.embedding, CachedEmbeddingModel) else None
    summ = (
        models.summarization.stats
        if isinstance(models.summarization, CachedSummarizationModel)
        else None
    )
    return cls(
        emb.hits if emb else 0,
        emb.misses if emb else 0,
        summ.hits if summ else 0,
        summ.misses if summ else 0,
        answerer.stats.hits,
        answerer.stats.misses,
    )

def as_tuple(self) -> tuple[int, ...]:
    return (
        self.emb_hits,
        self.emb_misses,
        self.sum_hits,
        self.sum_misses,
        self.qa_hits,
        self.qa_misses,
    )

def cost(self) -> dict[str, int]:
    return {
        "llm_calls": self.sum_misses + self.qa_misses,
        "embed_calls": self.emb_misses,
        "cache_hits": self.emb_hits + self.sum_hits + self.qa_hits,
        "cache_misses": self.emb_misses + self.sum_misses + self.qa_misses,
        "summary_calls": self.sum_misses,
        "answer_calls": self.qa_misses,
    }

def cache(self) -> DiskCache | None:
    if self._cache is None and get_settings().cache_enabled:
        self._cache = open_cache(get_settings().cache_dir)
    return self._cache

def articles(self, split: str) -> list[QualityArticle]:
