    kwargs: dict[str, Any] = {"splits_file": self.splits_file}
    if self.data_dir is not None:
        kwargs["data_dir"] = self.data_dir
    return load_split_articles(split, **kwargs)

def answerer(self, models: ModelBundle) -> MCQAnswerer:
    key = models.qa.model_id
    if key not in self._answerers:
        self._answerers[key] = MCQAnswerer.from_qa_model(models.qa, self.cache())
    return self._answerers[key]

def run_many(self, paths: Sequence[str | Path], *, force: bool = False) -> list[RunOutcome]:
    outcomes = []
    for p in paths:
        out = self.run_file(p, force=force)
        outcomes.append(out)
        if out.status == "quota":
            logger.error("daily quota exhausted; not starting the remaining configs")
            break
    return outcomes

def read_jsonl(path: str | Path) -> list[dict[str, Any]]:
    path = Path(path)
    if not path.exists():
        return []
    rows = []
    with path.open(encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if line:
                try:
                    rows.append(json.loads(line))
                except json.JSONDecodeError:  # a torn last line from an interrupted run
                    logger.warning("skipping unreadable line in %s", path)
    # Keep the last row per question (a resumed run never duplicates, but be safe).
    return list({r["question_id"]: r for r in rows}.values())

def list_runs(root: str | Path = DEFAULT_RUNS_DIR) -> list[dict[str, Any]]:
    """Summaries of every finished run, oldest first."""
    root = Path(root)
    if not root.exists():
        return []
    out = []
    for f in sorted(root.glob("*/summary.json")):
        try:
            out.append(json.loads(f.read_text(encoding="utf-8")))
        except json.JSONDecodeError:
            continue
    return sorted(out, key=lambda s: (s.get("created_at", ""), s.get("run_id", "")))

def load_run(
    run_id: str, root: str | Path = DEFAULT_RUNS_DIR
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """``(summary, results rows)`` for one run."""
    run_dir = Path(root) / run_id
    summary_file = run_dir / "summary.json"
    if not summary_file.exists():
        raise FileNotFoundError(f"no finished run {run_id!r} in {root}")
    return json.loads(summary_file.read_text(encoding="utf-8")), read_jsonl(
        run_dir / "results.jsonl"
    )

def find_run(name_or_id: str, root: str | Path = DEFAULT_RUNS_DIR) -> dict[str, Any]:
    """Look a run up by id, or by experiment name (the latest run with that name)."""
    runs = list_runs(root)
    for s in runs:
        if s["run_id"] == name_or_id:
            return s
    named = [s for s in runs if s.get("name") == name_or_id]
    if not named:
        raise KeyError(f"no run with id or name {name_or_id!r}")
    return named[-1]

@dataclass
class SplitSpec:
    name: str
    source: str  # QuALITY file split ("dev")
    set_ids: list[str]

def make_splits(
    articles: list[QualityArticle],
    *,
    seed: int = DEFAULT_SEED,
    size: int = DEFAULT_SIZE,
    source: str = "dev",
) -> dict[str, SplitSpec]:
    """Pick ``size`` sets for ``dev`` and ``size`` for ``confirm``, from disjoint articles.

    Only sets with gold labels are eligible. One set is taken per article.
    """
    by_article: dict[str, list[QualityArticle]] = {}
    for art in articles:
        if art.questions and all(q.gold_label is not None for q in art.questions):
            by_article.setdefault(art.article_id, []).append(art)
    article_ids = sorted(by_article)
    if len(article_ids) < 2 * size:
        raise ValueError(f"need {2 * size} articles, found {len(article_ids)}")
    rng = random.Random(seed)
    picked = rng.sample(article_ids, 2 * size)
    chosen = [rng.choice(sorted(by_article[a], key=lambda s: s.set_id)).set_id for a in picked]
    return {
        "dev": SplitSpec("dev", source, chosen[:size]),
        "confirm": SplitSpec("confirm", source, chosen[size:]),
    }

def save_splits(
    splits: dict[str, SplitSpec], path: str | Path = DEFAULT_SPLITS_FILE, *, seed: int
) -> Path:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    doc = {
        "seed": seed,
        "dataset": "QuALITY v1.0.1 (htmlstripped)",
        "splits": {name: {"source": s.source, "set_ids": s.set_ids} for name, s in splits.items()},
    }
    path.write_text(yaml.safe_dump(doc, sort_keys=False), encoding="utf-8")
    return path

def load_splits(path: str | Path = DEFAULT_SPLITS_FILE) -> dict[str, SplitSpec]:
    doc = yaml.safe_load(Path(path).read_text(encoding="utf-8"))
    return {
        name: SplitSpec(name, spec.get("source", "dev"), list(spec["set_ids"]))
        for name, spec in doc["splits"].items()
    }

def load_split_articles(
    name: str,
    *,
    splits_file: str | Path = DEFAULT_SPLITS_FILE,
    data_dir: str | Path = DEFAULT_DIR,
) -> list[QualityArticle]:
    """The question sets of split ``name``, in split order."""
    splits = load_splits(splits_file)
    if name not in splits:
        raise ValueError(f"unknown split {name!r}; available: {sorted(splits)}")
    spec = splits[name]
    by_id = {a.set_id: a for a in load_quality(spec.source, data_dir)}
    missing = [s for s in spec.set_ids if s not in by_id]
    if missing:
        raise ValueError(f"split {name!r} references unknown set ids: {missing}")
    return [by_id[s] for s in spec.set_ids]

@dataclass
class ModelBundle:
    embedding: BaseEmbeddingModel
    summarization: BaseSummarizationModel
    qa: BaseQAModel

def with_cache(bundle: ModelBundle, cache: DiskCache) -> ModelBundle:
    """Wrap every model in ``bundle`` with the disk cache (idempotent)."""
    emb = bundle.embedding
    summ = bundle.summarization
    qa = bundle.qa
    return ModelBundle(
        embedding=emb
        if isinstance(emb, CachedEmbeddingModel)
        else CachedEmbeddingModel(emb, cache),
        summarization=summ
        if isinstance(summ, CachedSummarizationModel)
        else CachedSummarizationModel(summ, cache),
        qa=qa if isinstance(qa, CachedQAModel) else CachedQAModel(qa, cache),
    )

def __init_subclass__(cls, **kwargs: Any) -> None:
    super().__init_subclass__(**kwargs)
    own = cls.__dict__
    inherits_impl = any(
        "embed_documents" in base.__dict__ or "create_embedding" in base.__dict__
        for base in cls.__mro__[1:]
        if base is not BaseEmbeddingModel and issubclass(base, BaseEmbeddingModel)
    )
    if "embed_documents" not in own and "create_embedding" not in own and not inherits_impl:
        raise TypeError(f"{cls.__name__} must implement embed_documents or create_embedding")
    if not cls.__dict__.get("model_id"):
        cls.model_id = cls.model_id or cls.__name__

def embed_documents(self, texts: Sequence[str]) -> np.ndarray:
    """Embed texts to be stored in the index. Returns a ``(len(texts), dim)`` array."""
    if type(self).create_embedding is BaseEmbeddingModel.create_embedding:
        raise NotImplementedError
    return np.asarray([self.create_embedding(t) for t in texts], dtype=np.float32)

def embed_query(self, text: str) -> np.ndarray:
    """Embed a search query. Defaults to document embedding."""
    return np.asarray(self.embed_documents([text])[0], dtype=np.float32)

def create_embedding(self, text: str) -> list[float]:
    """Original RAPTOR single-text API."""
    return [float(x) for x in self.embed_documents([text])[0]]

def stream_answer(self, context: str, question: str) -> Iterator[str]:
    """Yield the answer in pieces. Defaults to one piece."""
    yield self.answer_question(context, question)

@dataclass
class CacheStats:
    hits: int = 0
    misses: int = 0

@staticmethod
def key(*parts: Any) -> str:
    blob = json.dumps(parts, sort_keys=True, ensure_ascii=False, default=str).encode()
    return hashlib.sha256(blob).hexdigest()

def get(self, key: str) -> bytes | None:
    with self._lock:
        row = self._conn.execute("SELECT v FROM kv WHERE k = ?", (key,)).fetchone()
    return None if row is None else bytes(row[0])

def get_many(self, keys: Sequence[str]) -> dict[str, bytes]:
    out: dict[str, bytes] = {}
    with self._lock:
        for i in range(0, len(keys), 500):
            chunk = list(keys[i : i + 500])
            q = "SELECT k, v FROM kv WHERE k IN ({})".format(",".join("?" * len(chunk)))
            for k, v in self._conn.execute(q, chunk):
                out[k] = bytes(v)
    return out

def set_many(self, items: dict[str, bytes]) -> None:
    if not items:
        return
    with self._lock:
        self._conn.executemany("INSERT OR REPLACE INTO kv (k, v) VALUES (?, ?)", items.items())
        self._conn.commit()

def close(self) -> None:
    with self._lock:
        self._conn.close()

def _lookup(self, kind: str, texts: Sequence[str], compute) -> np.ndarray:
    keys = [DiskCache.key("emb", self.inner.model_id, kind, t) for t in texts]
    found = self.cache.get_many(list(dict.fromkeys(keys)))
    missing: dict[str, int] = {}  # unique missing key -> first position
    for i, k in enumerate(keys):
        if k not in found and k not in missing:
            missing[k] = i
    self.stats.misses += len(missing)
    self.stats.hits += len(texts) - len(missing)
    if missing:
        computed = np.asarray(compute([texts[i] for i in missing.values()]), dtype=np.float32)
        new = {k: computed[j].tobytes() for j, k in enumerate(missing)}
        self.cache.set_many(new)
        found.update(new)
    return np.stack([np.frombuffer(found[k], dtype=np.float32) for k in keys])

def embed_documents(self, texts: Sequence[str]) -> np.ndarray:
    if not texts:
        return np.zeros((0, 0), dtype=np.float32)
    return self._lookup("doc", texts, self.inner.embed_documents)

def summarize(self, context: str, max_tokens: int = 150) -> str:
    key = DiskCache.key("sum", self.inner.model_id, max_tokens, context)
    hit = self.cache.get(key)
    if hit is not None:
        self.stats.hits += 1
        return hit.decode("utf-8")
    self.stats.misses += 1
    out = self.inner.summarize(context, max_tokens)
    self.cache.set(key, out.encode("utf-8"))
    return out

def answer_question(self, context: str, question: str) -> str:
    key = DiskCache.key("qa", self.inner.model_id, context, question)
    hit = self.cache.get(key)
    if hit is not None:
        self.stats.hits += 1
        return hit.decode("utf-8")
    self.stats.misses += 1
    out = self.inner.answer_question(context, question)
    self.cache.set(key, out.encode("utf-8"))
    return out

def __getattr__(self, name: str) -> Any:
    # Expose extra methods of the wrapped model (e.g. structured MCQ answering).
    return getattr(self.inner, name)

def _make_client(api_key: str) -> Any:
    try:
        from google import genai
    except ImportError as exc:  # pragma: no cover - depends on extras
        raise ImportError("Gemini support needs `pip install raptor-code[gemini]`") from exc
    return genai.Client(api_key=api_key)

def _pool(api_key: str | None) -> KeyPool:
    keys = [api_key] if api_key else get_settings().require_gemini_keys()
    return shared_pool(keys, _make_client)

def _config(self, task_type: str | None):
    from google.genai import types

    return types.EmbedContentConfig(
        task_type=task_type, output_dimensionality=self.output_dimensionality
    )

def _embed(self, texts: Sequence[str], task_type: str | None) -> np.ndarray:
    clean = [(t.replace("\n", " ").strip() or " ") for t in texts]
    out: list[list[float]] = []
    for i in range(0, len(clean), self.batch_size):
        out.extend(self._embed_batch(clean[i : i + self.batch_size], task_type))
    return np.asarray(out, dtype=np.float32)

def _generate(self, prompt: str, **config: Any):
    from google.genai import types

    cfg = types.GenerateContentConfig(safety_settings=_safety_settings(), **config)
    return self._pool.call(
        self._bucket,
        self._rpm,
        lambda c: c.models.generate_content(model=self.model_name, contents=prompt, config=cfg),
    )

def generate_json(
    self, prompt: str, schema: dict[str, Any], *, temperature: float = 0.0
) -> str | None:
    """Generate a JSON reply that follows ``schema``. Returns the raw text (``None`` if filtered)."""
    resp = self._generate(
        prompt,
        temperature=temperature,
        response_mime_type="application/json",
        response_schema=schema,
    )
    return self._text(resp)

@staticmethod
def _text(resp: Any) -> str | None:
    try:
        text = resp.text
    except (ValueError, AttributeError):
        text = None
    return text.strip() if text else None

def summarize(self, context: str, max_tokens: int = 150) -> str:
    prompt = self.prompt_template.format(context=context, max_tokens=max_tokens)
    resp = self._generate(
        prompt, temperature=self.temperature, max_output_tokens=max_tokens * 2
    )
    text = self._text(resp)
    if text:
        return text
    logger.warning(
        "Gemini returned no summary text (likely filtered); using extractive fallback"
    )
    return context[:400].rstrip() + "..."

def answer_question(self, context: str, question: str) -> str:
    resp = self._generate(
        self.prompt_template.format(context=context, question=question),
        temperature=self.temperature,
    )
    return (
        self._text(resp)
        or "The model returned no answer (the response may have been filtered)."
    )

def stream_answer(self, context: str, question: str) -> Iterator[str]:
    from google.genai import types

    prompt = self.prompt_template.format(context=context, question=question)
    cfg = types.GenerateContentConfig(
        temperature=self.temperature, safety_settings=_safety_settings()
    )

    def start(client: Any):
        # Errors surface on the first chunk, so pull it inside the retried call.
        it = iter(
            client.models.generate_content_stream(
                model=self.model_name, contents=prompt, config=cfg
            )
        )
        return next(it, None), it

    first, rest = self._pool.call(self._bucket, self._rpm, start)
    for chunk in _chain(first, rest):
        if self._text(chunk):
            yield chunk.text

def _chain(first: Any, rest: Iterator[Any]) -> Iterator[Any]:
    if first is not None:
        yield first
    yield from rest

def hash_text(text: str) -> str:
    import hashlib

    return hashlib.sha256(text.encode()).hexdigest()[:8]

def is_retryable(exc: BaseException) -> bool:
    if is_rate_limit(exc):
        return True
    code = getattr(exc, "code", None)
    if isinstance(code, int) and code >= 500:
        return True
    text = str(exc).lower()
    return "unavailable" in text or "deadline" in text or "timed out" in text

def _cooldown_for(exc: BaseException) -> float:
    text = str(exc).lower()
    return DAILY_QUOTA_COOLDOWN if "perday" in text or "per day" in text else RATE_LIMIT_COOLDOWN

def _limiter(self, slot: KeySlot, bucket: str, rpm: int | None) -> RateLimiter:
    lim = slot.limiters.get(bucket)
    if lim is None or lim.rpm != (rpm if rpm and rpm > 0 else None):
        lim = slot.limiters[bucket] = RateLimiter(rpm)
    return lim

def cooldown(self, slot: KeySlot, bucket: str, seconds: float) -> None:
    with self._lock:
        slot.cooldown_until[bucket] = time.monotonic() + seconds

def _all_daily_exhausted(self, bucket: str) -> bool:
    now = time.monotonic()
    with self._lock:
        return all(
            s.disabled or s.cooldown_until.get(bucket, 0.0) - now > RATE_LIMIT_COOLDOWN
            for s in self.slots
        )

def call(self, bucket: str, rpm: int | None, fn: Callable[[Any], T], *, cost: int = 1) -> T:
    """Run ``fn(client)`` on an available key, failing over and retrying as needed.

    ``cost`` is how many requests the call counts as against ``rpm`` (Gemini's free
    tier counts every text in a batch embedding call as one request).
    """
    attempts = MAX_ATTEMPTS + len(self.slots)
    for attempt in range(attempts):
        slot = self.acquire(bucket, rpm, cost)
        try:
            return fn(slot.client)
        except Exception as exc:
            if is_auth_error(exc) and any(not s.disabled for s in self.slots if s is not slot):
                logger.warning(
                    "Gemini key #%d was rejected (%s); disabling it for this process",
                    slot.index + 1,
                    str(exc)[:80],
                )
                with self._lock:
                    slot.disabled = True
                continue
            if not is_retryable(exc) or attempt == attempts - 1:
                raise
            if is_rate_limit(exc):
                seconds = _cooldown_for(exc)
                logger.warning(
                    "Gemini key #%d rate-limited on %s; cooling down %.0fs%s",
                    slot.index + 1,
                    bucket,
                    seconds,
                    " (trying next key)" if len(self.slots) > 1 else "",
                )
                self.cooldown(slot, bucket, seconds)
                if FAIL_ON_DAILY_QUOTA and self._all_daily_exhausted(bucket):
                    raise QuotaExhaustedError(
                        f"daily quota used up on every key for {bucket}"
                    ) from exc
            else:
                delay = min(60.0, 2.0 * 2**attempt) * random.uniform(0.5, 1.0)
                logger.warning("Gemini call failed (%s); retrying in %.1fs", exc, delay)
                time.sleep(delay)
    raise RuntimeError("unreachable")  # pragma: no cover

def resolve_local_embedding(name: str) -> tuple[str, str, str]:
    """Map a model name or alias to ``(hub id, query prefix, document prefix)``."""
    if name in LOCAL_EMBEDDINGS:
        return LOCAL_EMBEDDINGS[name]
    for hub_id, q, d in LOCAL_EMBEDDINGS.values():
        if name == hub_id:
            return hub_id, q, d
    return name, "", ""

def _encode(self, texts: Sequence[str]) -> np.ndarray:
