        self.model.encode(
            list(texts),
            batch_size=self.batch_size,
            normalize_embeddings=self.normalize,
            show_progress_bar=False,
        ),
        dtype=np.float32,
    )

def __init__(
    self, model_name: str = "BAAI/bge-reranker-base", *, device: str | None = None
) -> None:
