        except KeyError as exc:
            raise not_found(f"run {exc.args[0]!r}") from None

    @api.get("/runs/{run_id}", response_model=S.RunDetail, tags=["runs"])
    def get_run(run_id: str) -> dict[str, Any]:
        try:
            return runs.load(run_id)
        except KeyError:
            raise not_found("run") from None

    # ------------------------------------------------------------------- code
    def code_call(fn: Callable[[], Any]) -> Any:
        try:
            return fn()
        except KeyError as exc:
            raise not_found(str(exc.args[0]) if exc.args else "code index") from None

    @api.get("/code", response_model=list[S.CodeRepo], tags=["code"])
    def list_code() -> list[dict[str, Any]]:
        return code.list_all()

    @api.get("/code/{code_id}/files", response_model=list[S.CodeFile], tags=["code"])
    def code_files(code_id: str) -> list[dict[str, Any]]:
        return code_call(lambda: code.files(code_id))

    @api.get("/code/{code_id}/file", response_model=S.CodeFileText, tags=["code"])
    def code_file(code_id: str, path: str) -> dict[str, Any]:
        return code_call(lambda: code.file_text(code_id, path))

    @api.get("/code/{code_id}/symbol/{nid}", response_model=S.CodeSymbol, tags=["code"])
    def code_symbol(code_id: str, nid: int) -> dict[str, Any]:
        return code_call(lambda: code.symbol(code_id, nid))

    @api.get("/code/{code_id}/graph", response_model=S.CodeGraph, tags=["code"])
    def code_graph(code_id: str, kinds: str | None = None) -> dict[str, Any]:
        wanted = [k for k in (kinds or "").split(",") if k] or None
        return code_call(lambda: code.graph(code_id, wanted))

    @api.post("/code/{code_id}/ask", tags=["code"], response_class=JSONResponse)
    def code_ask(code_id: str, req: S.CodeAskRequest):
        """SSE: ``token``… then ``citations`` (list of code hits) and ``done``."""
        idx = code_call(lambda: code.get(code_id))

        def events() -> Iterator[Event]:
            from .code import as_dict

            t0 = time.time()
            parts: list[str] = []
            for piece in idx.stream_ask(req.question, req.k):
                if isinstance(piece, str):
                    parts.append(piece)
                    yield "token", {"text": piece}
                else:
                    cites = [as_dict(c) for c in getattr(piece, "citations", [])]
                    yield "citations", {"citations": cites}
                    yield (
                        "answer",
                        {
                            "answer": getattr(piece, "answer", "".join(parts)),
                            "latency_s": round(time.time() - t0, 3),
                        },
                    )
            yield "done", {}

        return sse_response(events())

    app.include_router(api)
    _mount_frontend(app, settings.web_dist)

    return app

def _mount_frontend(app: FastAPI, dist: Path) -> None:
    index = dist / "index.html"
    if not index.is_file():

        @app.get("/", include_in_schema=False)
        def no_frontend() -> JSONResponse:
            return JSONResponse(
                {
                    "message": "The web UI is not built. Run `npm install && npm run build` in web/, "
                    "or use `npm run dev` there. The API is at /api and its docs at /docs."
                }
            )

        return
    if (dist / "assets").is_dir():
        app.mount("/assets", StaticFiles(directory=dist / "assets"), name="assets")

    @app.get("/{path:path}", include_in_schema=False)
    def spa(path: str) -> FileResponse:
        if path.startswith("api/"):
            raise HTTPException(404, "not found")
        candidate = (dist / path).resolve()
        if path and candidate.is_file() and dist.resolve() in candidate.parents:
            return FileResponse(candidate)
        return FileResponse(index)

def app_from_env() -> FastAPI:
    """Factory used by ``raptor serve --dev`` (uvicorn reload needs an import string)."""
    import os

    raw = os.environ.get("RAPTOR_SERVER_SETTINGS")
    settings = ServerSettings.model_validate_json(raw) if raw else ServerSettings()
    return create_app(settings)

def preset_config(name: str, overrides: dict[str, Any] | None = None) -> RaptorConfig:
    if name not in PRESETS:
        raise ValueError(f"unknown preset {name!r}; choose from {sorted(PRESETS)}")
    data = RaptorConfig().model_dump(mode="json")
    for patch in (PRESETS[name]["config"], overrides or {}):
        for section, values in patch.items():
            if isinstance(values, dict) and isinstance(data.get(section), dict):
                data[section].update(values)
            else:
                data[section] = values
    return RaptorConfig.model_validate(data)

def _context_key(texts: Sequence[str]) -> str:
    # Mirrors raptor.types.nodes_text, which builds the summarizer's input.
    return "".join(" ".join(t.splitlines()) + "\n\n" for t in texts)

def cost(self) -> dict[str, int]:
    return {
        "llm_calls": self.llm_calls,
        "embed_calls": self.embed_calls,
        "embedded_texts": self.embedded_texts,
    }

def __init__(self, inner: Chunker, tracker: _Tracker) -> None:
    self.inner = inner
    self.tracker = tracker

def split(self, text: str) -> list[Chunk]:
    chunks = self.inner.split(text)
    t = self.tracker
    with t.lock:
        t.texts = {i: c.text for i, c in enumerate(chunks)}
        t.layer_start, t.layer_count, t.layer = 0, len(chunks), 0
    t.job.emit(
        "chunks",
        {
            "count": len(chunks),
            "chars": len(text),
            "chunks": [
                {
                    "id": i,
                    "preview": preview(c.text, 90),
                    "tokens": len(t.tokenizer.encode(c.text, disallowed_special=())),
                }
                for i, c in enumerate(chunks)
            ],
        },
    )
    return chunks

def __init__(self, inner: ClusteringAlgorithm, tracker: _Tracker) -> None:
    self.inner = inner
    self.tracker = tracker

def as_dict(obj: Any) -> dict[str, Any]:
    if dataclasses.is_dataclass(obj) and not isinstance(obj, type):
        return dataclasses.asdict(obj)
    if isinstance(obj, dict):
        return obj
    if hasattr(obj, "model_dump"):
        return dict(obj.model_dump())
    return dict(vars(obj))

@property
def index_cls(self) -> Any:
    return _RealCodeIndex if self.real else StubCodeIndex

def _sources(self) -> dict[str, tuple[str, Path]]:
    out: dict[str, tuple[str, Path]] = {}
    if self.code_dir.is_dir():
        for d in sorted(self.code_dir.iterdir()):
            if d.is_dir() and _SAFE.match(d.name):
                out[d.name] = ("saved", d)
    if not self.real:
        for repo in self.stub_repos:
            if repo.is_dir():
                rid = f"{repo.name}-stub"
                out.setdefault(rid, ("stub-repo", repo))
    return out

def get(self, code_id: str) -> Any:
    if not _SAFE.match(code_id):
        raise KeyError(code_id)
    with self._lock:
        if code_id in self._loaded:
            return self._loaded[code_id]
    sources = self._sources()
    if code_id not in sources:
        raise KeyError(code_id)
    kind, path = sources[code_id]
    if kind == "saved":
        idx = self.index_cls.load(path)
    else:
        bundle = self.models()
        idx = StubCodeIndex.build(path, embedding_model=bundle.embedding, qa_model=bundle.qa)
    with self._lock:
        self._loaded[code_id] = idx
    return idx

def files(self, code_id: str) -> list[dict[str, Any]]:
    idx = self.get(code_id)
    symbols: dict[str, list[dict[str, Any]]] = {}
    for n in idx.tree.all_nodes.values():
        m = n.metadata
        if m.get("kind") in {"function", "method", "class", "symbol"} and m.get("path"):
            symbols.setdefault(m["path"], []).append(
                {
                    "id": n.index,
                    "symbol": m.get("symbol", ""),
                    "kind": m.get("kind", "symbol"),
                    "start_line": int(m.get("start_line", 0)),
                    "end_line": int(m.get("end_line", 0)),
                }
            )
    return [
        {
            "path": p,
            "language": LANGUAGES.get(Path(p).suffix, "text"),
            "symbols": sorted(symbols.get(p, []), key=lambda s: s["start_line"]),
        }
        for p in idx.files()
    ]

def file_text(self, code_id: str, path: str) -> dict[str, Any]:
    idx = self.get(code_id)
    if path not in set(idx.files()):
        raise KeyError(path)
    root = Path(str(idx.repo_path)).resolve()
    full = (root / path).resolve()
    if root not in full.parents:
        raise KeyError(path)
    text = full.read_text(encoding="utf-8", errors="replace")
    return {"path": path, "language": LANGUAGES.get(full.suffix, "text"), "text": text}

def symbol(self, code_id: str, nid: int) -> dict[str, Any]:
    out = self.get(code_id).symbol(nid)
    return {k: (as_dict(v) if k == "hit" else [as_dict(x) for x in v]) for k, v in out.items()}

def graph(self, code_id: str, kinds: list[str] | None) -> dict[str, Any]:
    idx = self.get(code_id)
    edges = [as_dict(e) for e in idx.graph(kinds or ["calls", "imports", "inherits"])]
    ids = {e["src"] for e in edges} | {e["dst"] for e in edges}
    nodes = []
    for i in sorted(ids, key=str):
        n = idx.tree.all_nodes.get(i) if isinstance(i, int) else None
        m = n.metadata if n is not None else {}
        nodes.append(
            {
                "id": i,
                "label": m.get("symbol") or str(i),
                "kind": m.get("kind", "symbol"),
                "path": m.get("path", ""),
                "start_line": int(m.get("start_line", 0) or 0),
                "layer": n.layer if n is not None else 0,
            }
        )
    return {"nodes": nodes, "edges": edges}

@dataclass
class CodeAnswer:
    answer: str
    citations: list[CodeHit] = field(default_factory=list)

@dataclass
class CodeEdge:
    src: int
    dst: int
    kind: str  # "calls" | "imports" | "inherits"

def _split_ident(text: str) -> set[str]:
    out = set()
    for tok in _IDENT.findall(text):
        for part in re.split(r"_|(?<=[a-z])(?=[A-Z])", tok):
            if len(part) > 2:
                out.add(part.lower())
    return out

@classmethod
def build(
    cls,
    repo_path: str | Path,
    config: Any = None,
    *,
    embedding_model: BaseEmbeddingModel | None = None,
    summarization_model: Any = None,
    qa_model: BaseQAModel | None = None,
    progress: Callable[[dict[str, Any]], None] | None = None,
) -> StubCodeIndex:
    from .fakes import FakeEmbeddingModel, FakeQAModel

    emb = embedding_model or FakeEmbeddingModel()
    root = Path(repo_path)
    progress = progress or (lambda _ev: None)
    files = sorted(
        p
        for p in root.rglob("*")
        if p.is_file()
        and p.suffix in TEXT_SUFFIXES
        and not (set(p.relative_to(root).parts) & SKIP_DIRS)
    )
    progress({"stage": "parsing", "total": len(files)})
    nodes: list[Node] = []
    by_name: dict[str, list[int]] = {}
    module_of: dict[str, int] = {}
    file_nodes: dict[str, int] = {}
    calls: list[tuple[int, str]] = []
    file_imports: list[list[str]] = []
    bases: list[tuple[int, str]] = []

    def add(
        text: str, layer: int, meta: dict[str, Any], children: set[int] | None = None
    ) -> int:
        n = Node(text, len(nodes), children or set(), {}, layer, meta)
        nodes.append(n)
        return n.index

    leaf_ids: list[int] = []
    file_specs: list[tuple[str, str, list[int]]] = []
    for f in files:
        rel = f.relative_to(root).as_posix()
        source = f.read_text(encoding="utf-8", errors="replace")
        lines = source.splitlines()
        symbols: list[int] = []
        mods: list[str] = []
        if f.suffix == ".py":
            try:
                mod = ast.parse(source)
            except SyntaxError:
                mod = ast.Module(body=[], type_ignores=[])
            for item in ast.walk(mod):
                if isinstance(item, (ast.Import, ast.ImportFrom)):
                    names = (
                        [a.name for a in item.names]
                        if isinstance(item, ast.Import)
                        else [item.module or ""]
                    )
                    mods.extend(n for n in names if n)
            for top in mod.body:
                for sym, parent in _symbols(top):
                    end = getattr(sym, "end_lineno", sym.lineno) or sym.lineno
                    qual = f"{parent}.{sym.name}" if parent else sym.name
                    kind = (
                        "class"
                        if isinstance(sym, ast.ClassDef)
                        else "method"
                        if parent
                        else "function"
                    )
                    body = "\n".join(lines[sym.lineno - 1 : min(end, sym.lineno + 59)])
                    doc = ast.get_docstring(sym) or ""
                    header = f"{rel} › {qual}"
                    nid = add(
                        f"# {header}\n{body}",
                        0,
                        {
                            "kind": kind,
                            "path": rel,
                            "start_line": sym.lineno,
                            "end_line": end,
                            "symbol": qual,
                            "docstring": doc,
                        },
                    )
                    symbols.append(nid)
                    by_name.setdefault(sym.name, []).append(nid)
                    for sub in ast.walk(sym):
                        if isinstance(sub, ast.Call):
                            fn = sub.func
                            name = (
                                fn.id
                                if isinstance(fn, ast.Name)
                                else fn.attr
                                if isinstance(fn, ast.Attribute)
                                else None
                            )
                            if name and name != sym.name:
                                calls.append((nid, name))
                    if isinstance(sym, ast.ClassDef):
                        for b in sym.bases:
                            if isinstance(b, ast.Name):
                                bases.append((nid, b.id))
            doc = ast.get_docstring(mod) or ""
        else:
            doc = " ".join(lines[:3])
        file_specs.append((rel, doc, symbols))
        file_imports.append(mods)
        leaf_ids.extend(symbols)

    # layer 1: files (a file with no symbols becomes its own leaf-level summary)
    imports: list[tuple[int, str]] = []
    for pos, (rel, doc, symbols) in enumerate(file_specs):
        names = [nodes[i].metadata["symbol"] for i in symbols]
        text = f"File {rel}. {doc.strip()} " + (
            f"Defines {', '.join(names[:12])}." if names else ""
        )
        nid = add(
            text.strip(),
            1 if symbols else 0,
            {
                "kind": "file",
                "path": rel,
                "start_line": 1,
                "end_line": len(
                    (root / rel).read_text(encoding="utf-8", errors="replace").splitlines()
                ),
                "symbol": rel,
            },
            set(symbols),
        )
        file_nodes[rel] = nid
        if rel.endswith(".py"):
            module_of[rel[:-3].replace("/", ".").removesuffix(".__init__")] = nid
        imports.extend((nid, m) for m in file_imports[pos])
    # layer 2: directories
    dirs: dict[str, set[int]] = {}
    for rel, nid in file_nodes.items():
        d = rel.rsplit("/", 1)[0] if "/" in rel else "."
        dirs.setdefault(d, set()).add(nid)
    dir_ids = []
    for d, members in sorted(dirs.items()):
        names = sorted(nodes[i].metadata["path"] for i in members)
        dir_ids.append(
            add(
                f"Directory {d} with {len(names)} files: {', '.join(names)}.",
                2,
                {"kind": "directory", "path": d, "start_line": 0, "end_line": 0, "symbol": d},
                members,
            )
        )
    add(
        f"Repository {root.name}: {len(file_nodes)} files, {len(leaf_ids)} symbols.",
        3,
        {"kind": "repo", "path": ".", "start_line": 0, "end_line": 0, "symbol": root.name},
        set(dir_ids),
    )

    edges: list[CodeEdge] = []
    for src, name in calls:
        for callee in by_name.get(name, [])[:3]:
            edges.append(CodeEdge(src, callee, "calls"))
    for src, name in bases:
        for base in by_name.get(name, [])[:1]:
            edges.append(CodeEdge(src, base, "inherits"))
    for src, mod_name in imports:
        dst: int | None = module_of.get(mod_name)
        if dst is None:
            # relative-ish: match on the last component
            tail = mod_name.rsplit(".", 1)[-1]
            dst = next((v for k, v in module_of.items() if k.endswith(tail) and v >= 0), None)
        if dst is not None and dst >= 0 and src >= 0 and src != dst:
            edges.append(CodeEdge(src, dst, "imports"))
    edges = list({(e.src, e.dst, e.kind): e for e in edges}.values())

    progress({"stage": "embedding", "total": len(nodes)})
    vecs = emb.embed_documents([n.text for n in nodes])
    for n, v in zip(nodes, vecs, strict=True):
        n.embeddings = {"EMB": np.asarray(v, dtype=np.float32)}
    layers: dict[int, list[Node]] = {}
    for n in nodes:
        layers.setdefault(n.layer, []).append(n)
    tree = Tree.from_layers(
        dict(sorted(layers.items())),
        {"embedding_key": "EMB", "embedding_model": emb.model_id, "kind": "code", "stub": True},
    )
    progress({"stage": "done", "num_nodes": len(nodes)})
    return cls(root, tree, edges, embedding_model=emb, qa_model=qa_model or FakeQAModel())

def save(self, path: str | Path) -> Path:
    path = Path(path)
    save_tree(self.tree, path)
    meta = {"repo_path": str(self.repo_path), "edges": [asdict(e) for e in self.edges]}
    (path / "code.json").write_text(json.dumps(meta), encoding="utf-8")
    return path

@classmethod
def load(cls, path: str | Path) -> StubCodeIndex:
    from .fakes import FakeEmbeddingModel, FakeQAModel

    path = Path(path)
    meta = json.loads((path / "code.json").read_text(encoding="utf-8"))
    return cls(
        Path(meta["repo_path"]),
        load_tree(path),
        [CodeEdge(**e) for e in meta["edges"]],
        embedding_model=FakeEmbeddingModel(),
        qa_model=FakeQAModel(),
    )

def update(self, progress: Callable[[dict[str, Any]], None] | None = None) -> StubCodeIndex:
    fresh = self.build(
        self.repo_path, embedding_model=self._embedding, qa_model=self._qa, progress=progress
    )
    self.tree, self.edges = fresh.tree, fresh.edges
    return self

def _extractive_answer(self, cites: list[CodeHit]) -> Iterator[str]:
    """Offline answer: describe the best-matching symbols from their docstrings."""
    if not cites:
        yield "No matching code was found."
        return
    sentences = []
    for i, h in enumerate(cites[:3]):
        doc = self.tree.all_nodes[h.node_index].metadata.get("docstring") or ""
        what = doc.strip().splitlines()[0].rstrip(".") if doc else f"is a {h.kind}"
        lead = "The most relevant code is" if i == 0 else "Related:"
        sentences.append(f"{lead} `{h.symbol}` in {h.path}: {what[:1].lower() + what[1:]}.")
    for word in " ".join(sentences).split(" "):
        yield word + " "

def ask(self, q: str, k: int = 6) -> CodeAnswer:
    final: CodeAnswer | None = None
    for piece in self.stream_ask(q, k):
        if isinstance(piece, CodeAnswer):
            final = piece
    assert final is not None
    return final

def files(self) -> list[str]:
    return sorted(
        n.metadata["path"]
        for n in self.tree.all_nodes.values()
        if n.metadata.get("kind") == "file"
    )

def graph(self, kinds: list[str] | tuple[str, ...] | None = None) -> list[CodeEdge]:
    want = set(kinds or ("calls", "imports", "inherits"))
    return [e for e in self.edges if e.kind in want]

def _symbols(node: ast.stmt, parent: str = "") -> Iterator[tuple[Any, str]]:
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        yield node, parent
    elif isinstance(node, ast.ClassDef):
        yield node, parent
        for child in node.body:
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                yield child, node.name

def _bucket(token: str) -> tuple[int, float]:
    h = int(hashlib.md5(token.encode()).hexdigest(), 16)
    return h % FAKE_DIM, 1.0 if (h >> 64) & 1 else -1.0

class FakeEmbeddingModel(BaseEmbeddingModel):
    """Signed feature hashing of content words and bigrams: shared vocabulary → similar vectors."""
    model_id = "fake:hash-embed-256"

def embed_documents(self, texts: Sequence[str]) -> np.ndarray:
    if not texts:
        return np.zeros((0, FAKE_DIM), dtype=np.float32)
    return np.stack([self._vector(t) for t in texts])

class FakeSummarizationModel(BaseSummarizationModel):
    """Extractive summary: the most central sentences of the input, in original order."""
    model_id = "fake:extractive-summary"

def summarize(self, context: str, max_tokens: int = 150) -> str:
    if self.delay:
        time.sleep(self.delay)
    sentences = [s.strip() for s in _SENTENCE.split(" ".join(context.split())) if s.strip()]
    if not sentences:
        return context[:200]
    freq: dict[str, int] = {}
    for w in _words(context):
        freq[w] = freq.get(w, 0) + 1

    def score(s: str) -> float:
        ws = _words(s)
        return sum(freq.get(w, 0) for w in ws) / (len(ws) + 3)

    ranked = sorted(range(len(sentences)), key=lambda i: (-score(sentences[i]), i))
    picked: list[int] = []
    budget = max(12, int(max_tokens * 0.75))
    used = 0
    for i in ranked:
        n = len(sentences[i].split())
        if picked and used + n > budget:
            continue
        picked.append(i)
        used += n
        if used >= budget:
            break
    text = " ".join(sentences[i] for i in sorted(picked))
    words = text.split()
    return " ".join(words[:budget]) + ("…" if len(words) > budget else "")

def stream_answer(self, context: str, question: str) -> Iterator[str]:
    for piece in self._compose(context, question):
        if self.delay:
            time.sleep(self.delay)
        yield piece

@staticmethod
def _best_sentences(context: str, question: str, n: int) -> list[str]:
    q = set(_words(question))
    sentences = [s.strip() for s in _SENTENCE.split(" ".join(context.split())) if s.strip()]
    scored = sorted(
        ((len(q & set(_words(s))), -i, s) for i, s in enumerate(sentences)), reverse=True
    )
    out = [s for score, _, s in scored[:n] if score > 0]
    return [s if len(s) < 280 else s[:277] + "…" for s in out]

def fake_bundle(delay: float = 0.0) -> ModelBundle:
    return ModelBundle(
        embedding=FakeEmbeddingModel(),
        summarization=FakeSummarizationModel(delay=delay * 4),
        qa=FakeQAModel(delay=delay),
    )

def preview(text: str, n: int = 220) -> str:
    flat = " ".join(text.split())
    return flat if len(flat) <= n else flat[: n - 1].rstrip() + "…"

def slugify(name: str) -> str:
    s = re.sub(r"[^A-Za-z0-9]+", "-", name.lower()).strip("-")
    return (s or "index")[:48]

@dataclass
class IndexEntry:
    id: str
    path: Path
    origin: str  # "demo" | "user"

@property
def mtime(self) -> float:
    return (self.path / TREE_FILE).stat().st_mtime

def entries(self) -> list[IndexEntry]:
    out: dict[str, IndexEntry] = {}
    for origin, root in (("demo", self.demo_dir), ("user", self.user_dir)):
        if not root.is_dir():
            continue
        for d in sorted(root.iterdir()):
            if d.is_dir() and (d / TREE_FILE).is_file() and _SAFE_ID.match(d.name):
                out.setdefault(d.name, IndexEntry(d.name, d, origin))
    return list(out.values())

def entry(self, index_id: str) -> IndexEntry:
    if not _SAFE_ID.match(index_id):
        raise KeyError(index_id)
    for e in self.entries():
        if e.id == index_id:
            return e
    raise KeyError(index_id)

def new_path(self, name: str, suffix: str) -> tuple[str, Path]:
    index_id = f"{slugify(name)}-{suffix}"
    return index_id, self.user_dir / index_id

def reembedded(tree: Tree, model: BaseEmbeddingModel) -> Tree:
    """A copy of ``tree`` whose node embeddings come from ``model`` (for offline demo mode)."""
    key = tree.embedding_key
    order = sorted(tree.all_nodes)
    vectors = model.embed_documents([tree.all_nodes[i].text for i in order])
    new = {
        i: Node(
            n.text,
            n.index,
            set(n.children),
            {key: np.asarray(v, dtype=np.float32)},
            n.layer,
            n.metadata,
        )
        for i, v in zip(order, vectors, strict=True)
        for n in [tree.all_nodes[i]]
    }
    layers = {layer: [new[n.index] for n in nodes] for layer, nodes in tree.layer_to_nodes.items()}
    meta = dict(tree.metadata)
    meta["embedding_model"] = model.model_id
    return Tree.from_layers(layers, meta)

def tokens(self, index: int) -> int:
    n = self._tokens.get(index)
    if n is None:
        text = self.tree.all_nodes[index].text
        n = self._tokens[index] = len(self.tokenizer.encode(text, disallowed_special=()))
    return n

def raptor(
    self,
    question: str,
    *,
    top_k: int | None = None,
    max_tokens: int | None = None,
    mode: str | None = None,
) -> RetrievalResult:
    retriever = TreeRetriever(self.tree, self.embedding, self.config, tokenizer=self.tokenizer)
    return retriever.retrieve(question, top_k=top_k, max_tokens=max_tokens, mode=mode)

def describe(self, picked: list[tuple[Node, float]]) -> dict[str, Any]:
    counts: dict[str, int] = {}
    nodes = []
    for node, score in picked:
        counts[str(node.layer)] = counts.get(str(node.layer), 0) + 1
        nodes.append(
            {
                "id": node.index,
                "layer": node.layer,
                "score": round(score, 4),
                "tokens": self.tokens(node.index),
                "preview": preview(node.text, 180),
            }
        )
    return {
        "nodes": nodes,
        "layer_counts": counts,
        "context_tokens": sum(n["tokens"] for n in nodes),
    }

def __init__(self, registry: IndexRegistry, models: Callable[[], ModelBundle], fake: bool):
    self.registry = registry
    self.models = models
    self.fake = fake
    self._cache: dict[str, tuple[float, Searcher]] = {}
    self._lock = threading.Lock()

def emit(self, event: str, data: dict[str, Any]) -> None:
    start = self.started_at or self.created_at
    payload = {**data, "t": round(time.time() - start, 3)}
    with self._cond:
        self.events.append((event, payload))
        self._cond.notify_all()

@property
def finished(self) -> bool:
    return self.status in TERMINAL

def stream(self, after: int = -1, keepalive: float = 10.0) -> Iterator[str]:
    """Replay events with id > ``after``, then follow live events until the job ends."""
    pos = max(after + 1, 0)
    while True:
        with self._cond:
            start = pos
            self._cond.wait_for(
                lambda start=start: len(self.events) > start or self.finished,  # type: ignore[misc]
                keepalive,
            )
            batch = self.events[pos:]
            finished = self.finished
        if not batch and not finished:
            yield ": keepalive\n\n"
            continue
        for event, data in batch:
            yield format_event(event, data, pos)
            pos += 1
        if finished and pos >= len(self.events):
            return

def __init__(self, workers: int = 1, keep: int = 50) -> None:
    self._pool = ThreadPoolExecutor(max_workers=workers, thread_name_prefix="raptor-job")
    self._jobs: dict[str, Job] = {}
    self._lock = threading.Lock()
    self.keep = keep

def get(self, job_id: str) -> Job:
    with self._lock:
        return self._jobs[job_id]

def all(self) -> list[Job]:
    with self._lock:
        return sorted(self._jobs.values(), key=lambda j: -j.created_at)

def _trim(self) -> None:
    done = [j for j in self._jobs.values() if j.finished]
    for j in sorted(done, key=lambda j: j.created_at)[: max(0, len(self._jobs) - self.keep)]:
        self._jobs.pop(j.id, None)

def _pca2(x: np.ndarray) -> np.ndarray:
    centered = x - x.mean(axis=0, keepdims=True)
    if len(x) < 2:
        return np.zeros((len(x), 2), dtype=np.float32)
    _, _, vt = np.linalg.svd(centered, full_matrices=False)
    out = centered @ vt[:2].T
    if out.shape[1] < 2:
        out = np.pad(out, ((0, 0), (0, 2 - out.shape[1])))
    return out

def _umap2(x: np.ndarray) -> np.ndarray:
    import umap

    n_neighbors = max(2, min(15, len(x) - 1))
    reducer = umap.UMAP(
        n_components=2, n_neighbors=n_neighbors, min_dist=0.15, metric="cosine", random_state=42
    )
    return np.asarray(reducer.fit_transform(x))

def project(tree: Tree, method: str = "umap") -> dict[str, Any]:
    indices, matrix = tree.normalized_matrix()
    if method == "umap" and len(indices) >= 6:
        try:
            coords = _umap2(matrix)
        except Exception:  # pragma: no cover - UMAP can fail on degenerate inputs
            logger.exception("UMAP failed; falling back to PCA")
            coords, method = _pca2(matrix), "pca"
    else:
        coords, method = _pca2(matrix), "pca"
    lo, hi = coords.min(axis=0), coords.max(axis=0)
    span = np.where(hi - lo == 0, 1.0, hi - lo)
    coords = (coords - lo) / span  # normalise to [0, 1]

    parents: dict[int, list[int]] = {i: [] for i in indices}
    for n in tree.all_nodes.values():
        for c in n.children:
            parents.setdefault(c, []).append(n.index)
    points = []
    for row, idx in enumerate(indices):
        node = tree.all_nodes[idx]
        ps = sorted(parents.get(idx, []))
        points.append(
            {
                "id": idx,
                "x": round(float(coords[row, 0]), 5),
                "y": round(float(coords[row, 1]), 5),
                "layer": node.layer,
                "parents": ps,
                "cluster": ps[0] if ps else None,
            }
        )
    return {"method": method, "points": points}

def cached_projection(
    tree: Tree, cache_dir: Path, key: str, method: str = "umap"
) -> dict[str, Any]:
    path = cache_dir / "projections" / f"{key}-{method}.json"
    if path.is_file():
        return dict(json.loads(path.read_text(encoding="utf-8")))
    with _LOCK:
        if path.is_file():
            return dict(json.loads(path.read_text(encoding="utf-8")))
        data = project(tree, method)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(data), encoding="utf-8")
    return data

