def save_tree(tree: Tree, path: str | Path) -> Path:
    """Write ``tree`` to the directory ``path`` atomically (replaces any existing index)."""
    path = Path(path)
    if path.exists() and path.is_file():
        raise FileExistsError(f"{path} is a file; pass a directory path for the new format")
    path.parent.mkdir(parents=True, exist_ok=True)

    order = sorted(tree.all_nodes)
    keys = sorted({k for n in tree.all_nodes.values() for k in n.embeddings})
    nodes_json = []
    for idx in order:
        n = tree.all_nodes[idx]
        nodes_json.append(
            {
                "index": n.index,
                "text": n.text,
                "children": sorted(n.children),
                "layer": n.layer,
                "metadata": n.metadata,
            }
        )
    doc: dict[str, Any] = {
        "format_version": FORMAT_VERSION,
        "num_layers": tree.num_layers,
        "metadata": tree.metadata,
        "embedding_keys": keys,
        "layers": {
            str(layer): [n.index for n in nodes] for layer, nodes in tree.layer_to_nodes.items()
        },
        "root_nodes": sorted(tree.root_nodes),
        "leaf_nodes": sorted(tree.leaf_nodes),
        "nodes": nodes_json,
    }
    matrices = {}
    for key in keys:
        rows = [tree.all_nodes[i].embeddings.get(key) for i in order]
        if any(r is None for r in rows):
            raise ValueError(f"embedding '{key}' is missing on some nodes")
        matrices[key] = np.asarray(rows, dtype=np.float32)

    tmp = Path(tempfile.mkdtemp(prefix=".tmp-", dir=path.parent))
    try:
        (tmp / TREE_FILE).write_text(json.dumps(doc, ensure_ascii=False), encoding="utf-8")
        np.savez_compressed(tmp / EMBEDDINGS_FILE, **matrices)  # type: ignore[arg-type]
        if path.exists():
            shutil.rmtree(path)
        os.replace(tmp, path)
    except BaseException:
        shutil.rmtree(tmp, ignore_errors=True)
        raise
    logger.info("Saved tree with %d nodes to %s", len(order), path)
    return path

def find_class(self, module: str, name: str) -> Any:
    if (module, name) in _ALLOWED_GLOBALS:
        return _ALLOWED_GLOBALS[(module, name)]
    if module in ("numpy", "numpy.core.multiarray", "numpy._core.multiarray") and name in (
        "ndarray",
        "dtype",
        "_reconstruct",
        "scalar",
    ):
        return super().find_class(module, name)
    raise pickle.UnpicklingError(f"refusing to load global {module}.{name} from legacy tree")

def load_legacy_pickle(path: str | Path) -> Tree:
    """Import a tree pickled by the original RAPTOR (``RetrievalAugmentation.save``)."""
    with open(path, "rb") as fh:
        obj = _RestrictedUnpickler(fh).load()
    if not isinstance(obj, _LegacyTree):
        raise ValueError(f"{path} does not contain a legacy RAPTOR Tree")
    legacy = obj.__dict__

    index_to_layer: dict[int, int] = {}
    for layer, nodes in legacy["layer_to_nodes"].items():
        for n in nodes:
            index_to_layer[n.__dict__["index"]] = int(layer)

    def convert(ln: _LegacyNode) -> Node:
        d = ln.__dict__
        return Node(
            text=d["text"],
            index=d["index"],
            children=set(d["children"]),
            embeddings={k: np.asarray(v, dtype=np.float32) for k, v in d["embeddings"].items()},
            layer=index_to_layer.get(d["index"], 0),
        )

    all_nodes = {i: convert(n) for i, n in legacy["all_nodes"].items()}
    layer_to_nodes = {
        int(layer): [all_nodes[n.__dict__["index"]] for n in nodes]
        for layer, nodes in legacy["layer_to_nodes"].items()
    }
    keys = {k for n in all_nodes.values() for k in n.embeddings}
    tree = Tree(
        all_nodes=all_nodes,
        root_nodes={i: all_nodes[i] for i in legacy["root_nodes"]},
        leaf_nodes={i: all_nodes[i] for i in legacy["leaf_nodes"]},
        num_layers=int(legacy["num_layers"]),
        layer_to_nodes=layer_to_nodes,
        metadata={
            "embedding_key": sorted(keys)[0] if len(keys) == 1 else "EMB",
            "source": "legacy-pickle",
        },
    )
    tree.validate()
    return tree

@property
def is_leaf(self) -> bool:
    return not self.children

@property
def embedding_key(self) -> str:
    return str(self.metadata.get("embedding_key", DEFAULT_EMBEDDING_KEY))

def validate(self) -> None:
    """Raise ``ValueError`` if the tree is internally inconsistent."""
    for idx, node in self.all_nodes.items():
        if idx != node.index:
            raise ValueError(f"node key {idx} != node.index {node.index}")
        missing = node.children - self.all_nodes.keys()
        if missing:
            raise ValueError(f"node {idx} has unknown children {sorted(missing)}")
    for layer, nodes in self.layer_to_nodes.items():
        for n in nodes:
            if n.layer != layer:
                raise ValueError(f"node {n.index} in layer list {layer} has layer {n.layer}")

@classmethod
def from_layers(
    cls,
    layer_to_nodes: dict[int, list[Node]],
    metadata: dict[str, Any] | None = None,
) -> Tree:
    all_nodes = {n.index: n for nodes in layer_to_nodes.values() for n in nodes}
    top = max(layer_to_nodes) if layer_to_nodes else 0
    return cls(
        all_nodes=all_nodes,
        root_nodes={n.index: n for n in layer_to_nodes.get(top, [])},
        leaf_nodes={n.index: n for n in layer_to_nodes.get(0, [])},
        num_layers=top,
        layer_to_nodes=layer_to_nodes,
        metadata=dict(metadata or {}),
    )

def _normalize_rows(matrix: np.ndarray) -> np.ndarray:
    if matrix.size == 0:
        return matrix
    norms = np.linalg.norm(matrix, axis=1, keepdims=True)
    norms[norms == 0] = 1.0
    return matrix / norms

def nodes_text(nodes: Iterable[Node]) -> str:
    """Join node texts the way the original RAPTOR did (one paragraph per node)."""
    return "".join(" ".join(n.text.splitlines()) + "\n\n" for n in nodes)

def fetch() -> None:
    from datasets import load_dataset

    DATA.mkdir(parents=True, exist_ok=True)
    rows = {}
    for name in ("princeton-nlp/SWE-bench_Lite", "princeton-nlp/SWE-bench"):
        for r in load_dataset(name, split="test"):
            if r["instance_id"] in SELECTED and r["instance_id"] not in rows:
                rows[r["instance_id"]] = {
                    k: r[k]
                    for k in ("instance_id", "repo", "base_commit", "patch", "problem_statement",
                              "version", "created_at")
                }  # fmt: skip
                rows[r["instance_id"]]["lite"] = r["instance_id"] in LITE
    missing = set(SELECTED) - rows.keys()
    if missing:
        raise SystemExit(f"instances not found: {sorted(missing)}")
    (DATA / "instances.json").write_text(
        json.dumps([rows[i] for i in SELECTED], indent=1, default=str), encoding="utf-8"
    )
    REPOS.mkdir(parents=True, exist_ok=True)
    for repo in sorted({r["repo"] for r in rows.values()}):
        dest = REPOS / repo.split("/")[1]
        if not dest.exists():
            log.info("cloning %s", repo)
            _git("clone", "--quiet", f"https://github.com/{repo}.git", str(dest))
    log.info("fetched %d instances", len(rows))

def gold_for(inst: dict, src: Path) -> tuple[set[str], set[str]]:
    from raptor.code.bench import gold_functions, patch_old_lines

    touched = patch_old_lines(inst["patch"])
    files = {p for p in touched if p.endswith(".py")}
    funcs: set[str] = set()
    for path in files:
        f = src / path
        if f.exists():
            funcs |= {f"{path}::{q}" for q in gold_functions(f.read_bytes(), path, touched[path])}
    return files, funcs

def load_index(repo: str):
    from raptor.code import CodeIndex

    return CodeIndex.load(REPOS[repo][1])

def _gold_source(repo: str, gold: list[str]) -> str:
    base = REPOS[repo][0]
    parts = []
    for g in gold:
        p = base / g
        files = sorted(p.rglob("*.py")) if p.is_dir() else [p]
        for f in files:
            body = f.read_text(encoding="utf-8")[:30000]
            parts.append(f"### {f.relative_to(base).as_posix()}\n{body}")
    return "\n\n".join(parts)

def run() -> None:
    from raptor.code.bench import judge_answer

    items = json.loads((DATA / "questions.json").read_text())
    out = DATA / "results.json"
    res = json.loads(out.read_text()) if out.exists() else {}
    indexes: dict = {}
    for n, it in enumerate(items):
        if str(n) in res:
            continue
        idx = indexes.setdefault(it["repo"], load_index(it["repo"]))
        row: dict = {"repo": it["repo"]}
        tree_text = idx.ask(it["q"], k=10).answer
        ctx, _ = idx._context(idx.search(it["q"], 10, **FLAT))
        flat_text = idx.models.qa.answer_question(ctx, it["q"])
        for name, text in (("tree", tree_text), ("flat", flat_text)):
            j = judge_answer(idx.models.qa, it["q"], it["reference"], text)
            row[name] = {k: j[k] for k in ("correctness", "completeness", "grounding", "comment")}
            row[name]["answer"] = text
            row[name]["cites_path_line"] = bool(re.search(r"\[[^\]\s]+:\d+", text))
        res[str(n)] = row
        out.write_text(json.dumps(res, indent=1), encoding="utf-8")
        logging.info("qa %d/%d", n + 1, len(items))

def report() -> str:
    res = json.loads((DATA / "results.json").read_text())
    rows = list(res.values())
    lines = [
        "| Repo | n | System | Correctness | Completeness | Grounding | Cites path:line |",
        "|---|---|---|---|---|---|---|",
    ]
    for repo in [*sorted({r["repo"] for r in rows}), "all"]:
        sub = [r for r in rows if repo == "all" or r["repo"] == repo]
        for system in ("tree", "flat"):
            m = [
                np.nanmean([r[system][k] for r in sub])
                for k in ("correctness", "completeness", "grounding")
            ]
            c = np.mean([r[system]["cites_path_line"] for r in sub])
            cells = " | ".join(f"{x:.2f}" for x in m)
            lines.append(f"| {repo} | {len(sub)} | {system} | {cells} | {c:.0%} |")
    return "\n".join(lines)

def main() -> None:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    ap.add_argument("--out", type=Path, default=Path("data/quality"))
    ap.add_argument("--from-local", type=Path, help="Path to a local clone of nyu-mll/quality")
    args = ap.parse_args()
    args.out.mkdir(parents=True, exist_ok=True)

    if args.from_local:
        src = args.from_local / "data" / "v1.0.1"
        for split in SPLITS:
            shutil.copy2(src / NAME.format(split=split), args.out)
    else:
        print(f"Downloading {URL} ...")
        with urllib.request.urlopen(URL, timeout=120) as resp:
            data = resp.read()
        with zipfile.ZipFile(io.BytesIO(data)) as zf:
            for split in SPLITS:
                member = next(n for n in zf.namelist() if n.endswith(NAME.format(split=split)))
                (args.out / NAME.format(split=split)).write_bytes(zf.read(member))
    for split in SPLITS:
        path = args.out / NAME.format(split=split)
        print(f"  {path}  ({path.stat().st_size / 1e6:.1f} MB)")

def describe(factor: str, v: dict) -> str:
    if factor == "chunking":
        return f"{v['strategy']}-{v['max_tokens']}"
    if factor == "clustering":
        return v["strategy"]
    if factor == "retrieval":
        return v["mode"] + ("+" + v["hybrid"] if v.get("hybrid") else "")
    return v["model"]

