class Cart:
    """A shopping cart that holds line items and computes totals."""
    currency = "EUR"

def __init__(self, owner: str) -> None:
    self.owner = owner
    self.items: dict[str, tuple[int, float]] = {}

def add_item(self, sku: str, quantity: int, unit_price: float) -> None:
    """Add ``quantity`` units of ``sku`` to the cart."""
    if quantity <= 0:
        raise ValueError("quantity must be positive")
    old_qty, _ = self.items.get(sku, (0, unit_price))
    self.items[sku] = (old_qty + quantity, unit_price)

def remove_item(self, sku: str) -> None:
    """Remove every unit of ``sku`` from the cart."""
    self.items.pop(sku, None)

def subtotal(self) -> float:
    """Sum of quantity times unit price over all items."""
    return sum(qty * price for qty, price in self.items.values())

def total(self, discount_code: str | None = None) -> float:
    """Subtotal after applying the discount code, if any."""
    amount = self.subtotal()
    if discount_code:
        amount = apply_discount(amount, discount_code)
    return round(amount, 2)

def loyalty_total(self) -> float:
    """Total for loyalty members: a flat ten percent off."""
    rule = PercentRule(10)
    return rule.apply(self.subtotal())

def validate_payment(amount_cents: int, total_cents: int) -> None:
    if amount_cents < total_cents:
        raise PaymentError(f"payment {amount_cents} is less than total {total_cents}")

@dataclass
class LineItem:
    product: Product
    quantity: int = 1

def subtotal(self) -> int:
    """Price of this line before discounts."""
    return self.product.price_cents * self.quantity

@dataclass
class Cart:
    """Items a customer intends to buy."""
    items: list[LineItem] = field(default_factory=list)
    coupon: str | None = None

def add(self, product: Product, quantity: int = 1) -> None:
    """Add a product, merging with an existing line for the same SKU."""
    for item in self.items:
        if item.product.sku == product.sku:
            item.quantity += quantity
            return
    self.items.append(LineItem(product, quantity))

def subtotal(self) -> int:
    """Sum of all line subtotals, in cents."""
    return sum(item.subtotal() for item in self.items)

def apply(self, amount: float) -> float:
    """Return the price after this rule; the base rule changes nothing."""
    return amount

def __init__(self, percent: float) -> None:
    if not 0 <= percent <= 100:
        raise ValueError("percent must be between 0 and 100")
    self.percent = percent

def apply(self, amount: float) -> float:
    """Reduce ``amount`` by ``percent`` percent."""
    return amount * (100 - self.percent) / 100

def apply_discount(amount: float, code: str) -> float:
    """Apply the discount registered for ``code``; unknown codes raise KeyError."""
    percent = DISCOUNT_CODES[code.upper()]
    return PercentRule(percent).apply(amount)

def tax_for(region: str, amount: float) -> float:
    """Value-added tax owed on ``amount`` in ``region`` (default 20 percent)."""
    rates = {"de": 0.19, "fr": 0.2, "uk": 0.2}
    return amount * rates.get(region.lower(), 0.2)

def load_orders(path: Path = ORDERS) -> list[dict]:
    """Read every saved order (an empty list if there are none yet)."""
    if not path.exists():
        return []
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line]

def load_cart(self, owner: str) -> Cart:
    """Load the cart saved for ``owner`` (an empty cart if there is none)."""
    cart = Cart(owner)
    row = self.conn.execute("SELECT items FROM carts WHERE owner = ?", (owner,)).fetchone()
    if row:
        cart.items = {k: tuple(v) for k, v in json.loads(row[0]).items()}
    return cart

def test_tree_structure_is_consistent(document, embedder, summarizer):
    events = []
    tree = TreeBuilder(small_config(), embedder, summarizer).build_from_text(
        document, progress=events.append
    )
    tree.validate()
    assert tree.num_layers >= 1
    assert set(tree.layer_to_nodes) == set(range(tree.num_layers + 1))
    for layer in range(1, tree.num_layers + 1):
        below = {n.index for n in tree.layer_to_nodes[layer - 1]}
        for node in tree.layer_to_nodes[layer]:
            assert node.children and node.children <= below
    # every lower-layer node has at least one parent
    for layer in range(tree.num_layers):
        parents = {c for n in tree.layer_to_nodes[layer + 1] for c in n.children}
        assert {n.index for n in tree.layer_to_nodes[layer]} <= parents
    assert tree.root_nodes == {n.index: n for n in tree.layer_to_nodes[tree.num_layers]}
    assert events[0]["stage"] == "chunking" and events[-1]["stage"] == "done"
    # leaves carry their source offsets
    leaf = tree.leaf_nodes[0]
    assert document[leaf.metadata["start"] : leaf.metadata["end"]] == leaf.text
    # embeddings are batched: one call per layer, not one per chunk
    assert embedder.doc_calls == tree.num_layers + 1

